INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Fox Adventures', 'Star Fox Adventures takes place in a vast 3-D world full of strange scenery, brain-teasing puzzles and intense action. Learn the secrets of a mystical staff to fend off enemies and cast a variety of spells. Plus the intuitive, enemy-locking target system allows you to battle foes without skipping a beat. And you''ll need to build clever strategies to defeat the huge boss enemies.' FROM games WHERE igdb_id = 2686 ON CONFLICT (game_id, language_code) DO NOTHING;
