INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Die Bücher Luzifers', 'Die Bücher Luzifers is the second game of German RPG Maker developer Kelven and is yet another horror game. While influcenes of Silent Hill and Resident Evil do exist in this one, they''re more subtile and the plotline and world do feel a lot more unique, then in the first game.' FROM games WHERE igdb_id = 268865 ON CONFLICT (game_id, language_code) DO NOTHING;
