INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('izumi-jiken-file-vol-1-shiosai-hen', 292102, '2002-09-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7wyw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scr9a1.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Izumi Jiken File Vol. 1 - Shiosai-hen', 'A visual novel-style detective game released for Japanese mobile phones. Originally debuting in 2002, it was rereleased on May 1, 2006 with updated graphics as Izumi Jiken File Vol. 1 - Shiosai-hen Deluxe Edition. You can easily feel like a detective by reading a novel! "Mystery Adventure Izumi Case File - Shiosai Edition" (hereinafter referred to as Izumi Case File) is a mystery adventure game that "deduces the criminal" based on the situation at the crime scene and the information collected by asking.' FROM games WHERE igdb_id = 292102 ON CONFLICT (game_id, language_code) DO NOTHING;
