INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Document of Metal Gear Solid 2', 'The Document of Metal Gear Solid 2 gives a behind-the-scenes look at Metal Gear Solid 2: Sons of Liberty. You''ll receive a thorough education on all aspects of Sons of Liberty, including original concept plans, rare video footage and trailers, and even programming secrets. Also included are playable VR training missions from Metal Gear Solid 2: Substance. With in-depth footage and insider information, The Document of Metal Gear Solid 2 is a complete resource guide for Metal Gear Solid fans.' FROM games WHERE igdb_id = 139343 ON CONFLICT (game_id, language_code) DO NOTHING;
