INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Skies of Arcadia Legends', 'Battle to Save Arcadia! You are Vyse, a young pirate on a quest to save Arcadia. Wage battle against an evil Empire as you make a name for yourself on land and in the sky. Will you become a Legend? -New "Wanted" Battles, new characters, weapons, and more! -An improved battle engine featuring spectacular special attacks -Experience the Director''s Cut with hours of new gameplay! -Employ devastating weapons and magic -Explore a full 3D world to recruit up to 22 crew members' FROM games WHERE igdb_id = 4152 ON CONFLICT (game_id, language_code) DO NOTHING;
