INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gakuen-toshi-vara-noir', 3926, '2002-10-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6tu3.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gakuen Toshi Vara Noir', 'The threat of demonic invasion gives impetus to the fledgling Simba Empire to found a school of magic called Vara Noir. With the world recovering after a devastating war, the Empire uses the school to train students in the ways of battle and magic to prepare for any imminent and far-off threats. Enter 13-year old chimney sweeper Myu who cleans smokestacks and other debris laden orifices. One day, her grandpappy hands her a mighty sword and a few ducats and commands her to apply to Vara Noir for an education in the mystic arts. Myu takes the entrance examination and passes with flying colors. As such, she enters Vara Noir academy and goes on an adventure where she will eventually help save the kingdom. Idea Factory''s latest game in the Kingdom of Chaos series features dungeon exploration, character interaction and an Megami-Tensei-esque item synthesis system where special items found in dungeons may be bonded with weapons to increase attack power, imbue properties, etc. Interaction sequences are of the point ''n click sort where questions and answers are rattled off in routine fashion. Originally released on the PS2, Gakuen Toshi Vara Noir joins the Gamecube library with new animation sequences and graphical updates which freshen up the adventure for old and new gamers to enjoy.' FROM games WHERE igdb_id = 3926 ON CONFLICT (game_id, language_code) DO NOTHING;
