INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dexter''s Laser Lab', 'Dexter''s Laser Lab is a Shockwave game based on Dexter''s Laboratory that was playable on the official Cartoon Network website. In this game, Dee Dee celebrates her birthday by having a party in Dexter''s laboratory, leaving behind many balloons in her wake. Dexter, using his invention called the TidyTron 4000, a high-powered infrared laser, works to get rid of the balloons in his laboratory.' FROM games WHERE igdb_id = 241143 ON CONFLICT (game_id, language_code) DO NOTHING;
