INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Silent Scope: Fortune Hunter', 'Silent Scope: Fortune Hunter is a rail shooter developed and published by Konami. It is the fifth game in the Silent Scope series, and was released in the year 2002. The cabinet, bundled with Silent Scope EX, also features a Prize Mode where the player can earn real money payouts for performing well in-game.' FROM games WHERE igdb_id = 361924 ON CONFLICT (game_id, language_code) DO NOTHING;
