INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tom Clancy''s Splinter Cell', 'Infiltrate terrorists'' positions, acquire critical intelligence by any means necessary, execute with extreme prejudice, and exit without a trace! You are Sam Fisher, a highly trained secret operative of the NSA''s secret arm: Third Echelon. The world balance is in your hands, as cyber terrorism and international tensions are about to explode into WWIII.' FROM games WHERE igdb_id = 910 ON CONFLICT (game_id, language_code) DO NOTHING;
