INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Airplane Tycoon: Evolution', 'In 2002, Airline Tycoon Evolution, second Airline Tycoon re-release was published by Monte Cristo. The game introduced ten new missions, possibility of buying self-designed aircraft (and possibility of sharing these planes via Internet), possibility of hiring aircraft security agents, five new sabotages and more.' FROM games WHERE igdb_id = 306640 ON CONFLICT (game_id, language_code) DO NOTHING;
