INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Strategic Command: European Theater', 'Strategic Command: European Theater is a World War II grand strategy game. The game, that is turn-based, takes place on a map that stretches horizontally from the east coast of North America to the Ural Mountains in Russia, and vertically from just below the Arctic Circle to the North Coast of Africa. There are six campaigns, each a year in the war that are played until the end of the war, starting with the Germans attacking Poland.' FROM games WHERE igdb_id = 51892 ON CONFLICT (game_id, language_code) DO NOTHING;
