INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hey Arnold! The Movie', 'Based on the Hey Arnold! The Movie coming to theaters June 21, 2002. Follow Arnold and friends through a whirlwind adventure to try and save the neighborhood from a mean businessman who wants to build a Super Beeper Emporium. Throughout different levels of the game, help Arnold sneak past security guards, Gerald as he gets the word out for the Blockapalooza party, and Grandma as she escapes from jail!' FROM games WHERE igdb_id = 6565 ON CONFLICT (game_id, language_code) DO NOTHING;
