INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chemicus II: Die versunkene Stadt', 'A famous professor disappears during an accident in a chemistry laboratory. As his assistant, it is the player''s job to find him and solve the mystery around this accident. The player has to find solutions to puzzles with the help of chemistry. The necessary ingredients are stored in the inventory. The game includes a knowledge base.' FROM games WHERE igdb_id = 284656 ON CONFLICT (game_id, language_code) DO NOTHING;
