INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Road Trip', 'Road Trip is the second game in the "Choro Q HG" series of games developed exclusively for the PlayStation 2 console. Take a road trip to adventure! Right off the starting line, Road Trip matches action with depth, allowing you to customize your ride for over 100 different events. Wins earn cash, which you use to buy parts and upgrade your vehicles. From engines to brakes, body types to paint jobs, the parts store stocks over 250 interchangeable components. Top that with 20 mini-games, special missions and dozens of hidden surprises and you don''t just have a racing adventure - you''ve got a road trip!' FROM games WHERE igdb_id = 44694 ON CONFLICT (game_id, language_code) DO NOTHING;
