INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Goobs', 'Goobs is a top‑down puzzle‑action game for Windows developed by Redclaw Software. You control adorable yellow creatures stranded on floating platforms in space, guiding them to exits while collecting energy orbs and overcoming obstacles. Featuring 55 handcrafted levels, a powerful built‑in level editor, and a custom level browser, Goobs offers creative challenges with multiple solutions and robust replay value. Originally shareware, it later became freeware, celebrated by fans for its clever puzzles, charming presentation, and community‑driven content.' FROM games WHERE igdb_id = 354042 ON CONFLICT (game_id, language_code) DO NOTHING;
