INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The King of Route 66', 'The King of Route 66 is the arcade racing game sequel to 18 Wheeler: American Pro Trucker. It was later brought to the PlayStation 2 by Tose. This game features a story mode in which the Evil Tornado Corporation has taken over all the trucking jobs along Route 66. You play a hero trucker who challenges Tornado drivers all along the route and puts them in their place by getting your cargo to the destination first.' FROM games WHERE igdb_id = 18863 ON CONFLICT (game_id, language_code) DO NOTHING;
