INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tomb Raider: The Prophecy', 'Tomb Raider: The Prophecy is the first game for the Gameboy Advance. Lara is now in a quasi-3D overhead environment, as opposed to the 2D-platformer view of the previous handheld versions. This view proves helpful while Lara runs, jumps, shimmys, and shoots around. Although there is lack of a save feature, there is a password system which lets you restore back to ''almost'' where you left.' FROM games WHERE igdb_id = 18809 ON CONFLICT (game_id, language_code) DO NOTHING;
