INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('colin-mcrae-rally-3', 7968, '2002-10-25', 84, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1otn.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sce9qm.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Colin McRae Rally 3', 'You are given 3 seasons to win the world rally championship, racing the Ford Focus RS RWC. In each season there are 8 competitions, staged in Australia, the USA, England, Sweden, Japan, Greece and Finland. Each competition has 6 stages set around different landscapes, and a special head-to-head stage at the end. You are out to beat the clock, and the time set by the opposing teams, on each occasion. Beat the time, win the stage, and you are once step closer to taking the world title. Along the way you can alter and modify the Focus'' setup, from the wheels used, gearboxes, brakes, suspension and so forth. You can also test drive the car before any event to make sure the setup is to your liking.' FROM games WHERE igdb_id = 7968 ON CONFLICT (game_id, language_code) DO NOTHING;
