INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chase: Hollywood Stunt Driver', 'Chase places you in the exciting world of Hollywood-movie stunt-car action. In the game, you take the role of Chase Corrada, a young stuntwoman who is starting her promising career as a movie stunt driver. In four unique sets--including a gangster set, a postapocalyptic set, and more--it''s up to you to perfect the film''s action sequences. You''ll drive not only traditional 4-wheeled vehicles but also motorcycles and a 3-wheeled Ramen delivery Tuk-Tuk. You''ll have to hit your marks as you attempt jumps, smash through props, and race through the set to please the director.' FROM games WHERE igdb_id = 5774 ON CONFLICT (game_id, language_code) DO NOTHING;
