INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Live for Speed', 'Live for Speed (LFS) is a racing simulator developed by a three-person team comprising Scawen Roberts, Eric Bailey, and Victor van Vlaardingen. The main focus is to provide a realistic racing experience for the online multiplayer game and to allow single player races against AI cars.' FROM games WHERE igdb_id = 9492 ON CONFLICT (game_id, language_code) DO NOTHING;
