INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Final Fantasy X International', 'Final Fantasy X International is the Japanese re-release of Final Fantasy X with content not available in the original japanese release. These include battles with dark versions of the game''s aeons, the superboss Penance, and various added scenes. It also contains a video clip of 12 minutes, Eternal Calm, bridging the gap with the sequel Final Fantasy X-2.' FROM games WHERE igdb_id = 146774 ON CONFLICT (game_id, language_code) DO NOTHING;
