INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Auto Modellista', 'Handle the road like a pro with your own customizable racing machine or your choice of more than 60 top-of-the-line models. Race vehicles from manufacturers, including Toyota, Nissan, Honda, Subaru, and Mitsubishi, against up to eight drivers online or up to two drivers in split-screen mode. You''ll tear past spectators, maneuver your way through tight mountain passes, and round each corner of the race track in your dream car at lightning speeds.' FROM games WHERE igdb_id = 3791 ON CONFLICT (game_id, language_code) DO NOTHING;
