INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('fire-blade', 3916, '2002-06-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1ov8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scedrk.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fire Blade', 'Fire Blade is a flight simulation video game released in 2002 by Kuju Entertainment. In the game, the player takes control of an advanced helicopter gunship as a part of the Fire Blade task force, which in the arc of the game''s story is responsible for fighting terrorism. The enemies of the game are the United Eastern States, who are believed to be building terrorist training camps and factories for weapons of mass destruction. The game is similar in many respects to ThunderHawk: Operation Phoenix. However, in Fire Blade, the player is forced to be far less cautious unless on a stealth mission and is usually pitted against far larger amounts of enemies. The main element of the game is aggressively piloting the player''s attack helicopters against large enemy armored formations and completing the main mission objectives, these vary in creativity from simply blowing up a bridge to aiding a special forces team in stopping a train by parking a truck across the tracks and stopping enemy troops from moving it. A secondary element of the game is FPS-style sniping, when the player''s helicopter enters "stealth mode" the autocannon is used as a precision sniper weapon that can be used to accurately target individual soldiers, allowing the player to snipe enemy infantry much like in an FPS. Additional fuel and ammunition for the helicopter''s jet boosters and heavier armaments are acquired from destroyed enemy vehicles instead of the more conventional reloading areas from games such as the Strike Series.' FROM games WHERE igdb_id = 3916 ON CONFLICT (game_id, language_code) DO NOTHING;
