INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WizMo''s Workshop: Dragons of Frozzbokk', 'WizMo''s Workshop: Dragons of Frozzbokk is an educational game created for kids aged three to six. It is meant to stimulate the imagination of children and teaches color and shape recognition while developing hand-eye coordination. Children can explore the Workshop, help WizMo build different machines, collect prizes to show off to their friends, and learn while playing with WizMo''s little dragons.' FROM games WHERE igdb_id = 94577 ON CONFLICT (game_id, language_code) DO NOTHING;
