INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jonny Moseley: Mad Trix', 'Jonny Moseley''s bringin'' new-school skills to the world''s first trick-based skiing game! Rack up big points with tons of tricks including the Tai Pan, Illegal, and Moseley''s signature move, the Dinner Roll. Get heli-dropped onto a mountain to huck yourself off every object that you can find. Take new school skiing to the max!' FROM games WHERE igdb_id = 49336 ON CONFLICT (game_id, language_code) DO NOTHING;
