INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'V-Rally 3', 'Strap yourself in for the most intense and lifelike rally racing you''ve ever experienced. Introducing V-Rally 3, the next evolution in the leading rally racing franchise that has sold over 5 million copies worldwide. Everything about V-Rally 3, from the highly detailed cars to the meticulously handcrafted tracks, creates unprecedented racing realism. V-Rally 3... It leaves everything else in the dust!' FROM games WHERE igdb_id = 4227 ON CONFLICT (game_id, language_code) DO NOTHING;
