INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Die Hard: Nakatomi Plaza', 'The game is a first-person shooter that follows the plot of the first Die Hard film. Players take the role of John McClane, and try to stop the terrorist attack on the Nakatomi Plaza. The game''s levels are based on the sets from the film. The various action scenes from the film have also been recreated. The game expands on the film''s plot, and adds a few missions not found in the film, such as escorting a SWAT team around the building or saving various hostages stranded on various floors of the building.' FROM games WHERE igdb_id = 18219 ON CONFLICT (game_id, language_code) DO NOTHING;
