INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monsters, Inc.: Wreck Room Arcade - Monster Tag', 'This game is part of the Wreck Room Arcade series which consists of four different "activities". You can buy and play them separately, but they link into the same main menu - and, if you have bought them all, you get another bonus game for free (it will be unlocked after you''ve installed the last game). In this game, you control a figure on some sort of paddle. Another figure will jump on the other end of the paddle and, if you press space in the right moment, it will be sent back in the air where some gadgets are. These gadgets need to be collected to advance a level.' FROM games WHERE igdb_id = 72181 ON CONFLICT (game_id, language_code) DO NOTHING;
