INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Kim Possible: Revenge of Monkey Fist', 'Revenge of Monkey Fist is a sidescrolling platformer where players take control of Kim Possible. Kim has an assortment of punches, kicks and acrobatic moves that she can use to dispatch enemies. She''s not short of high-tech gadgets, either: she can use laser lipstick, compact case bombs, invincibility watches, to name a few. Kim''s buddy Wade can also contact her from time to time to provide Kim with useful tips and hints.' FROM games WHERE igdb_id = 49275 ON CONFLICT (game_id, language_code) DO NOTHING;
