INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crash Bandicoot: Warped - Collector''s Edition', 'The Collectors'' Edition version of Crash Bandicoot: Warped. This game is part of a trilogy released in the Crash Bandicoot Collectors'' Edition boxset. This version is mostly the same as the original. The only key difference is the words "Collectors'' Edition" on both the disc and manual. The manual also has a white Playstation banner instead of the typical black banner.' FROM games WHERE igdb_id = 43682 ON CONFLICT (game_id, language_code) DO NOTHING;
