INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('stronghold-crusader', 964, '2002-07-31', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7nlx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scq6jn.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stronghold Crusader', 'Stronghold: Crusader is the successor to Firefly Studios''s 2001 game Stronghold. Crusader has much in common with the original Stronghold, but differs from its predecessor in the fact that the game is no longer set in a pseudo-Europe, instead being set in the Middle East during the Crusades. The game features a multitude of new Arabian units that can be purchased in a new building, the mercenary post. Though the Arabian troops do not require any weapons to produce, they are rather expensive. The game was also released as Stronghold Warchest. This version was a compendium of Stronghold and an enhanced version of Stronghold: Crusader, containing additional characters and an additional Crusader Trail. Stronghold Warchest was only released in limited number of countries (i. e. USA or Poland), meaning players in the rest of the world have never encountered the second Crusader Trail, or second set of characters. This changed when an updated version of Stronghold Crusader, Stronghold: Crusader Extreme was released in early 2008.' FROM games WHERE igdb_id = 964 ON CONFLICT (game_id, language_code) DO NOTHING;
