INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Cloud 2', 'BUILD your world. INVENT your weapons. CREATE your adventure. Discover a secret binding the past, present and future. A secret where an innocent inventor, a temporal warrior and an ageless evil hold the key. Experience an epic action/RPG adventure that relies on your innovation as much as exploration and fighting reflexes.' FROM games WHERE igdb_id = 1215 ON CONFLICT (game_id, language_code) DO NOTHING;
