INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Microsoft: My Personal Tutor 1st & 2nd Grade', 'Come along with Professor Presto on a fun-filled learning journey--from outer space to beneath the sea, to a museum brimming with adventure. Microsoft My Personal Tutor: 1st & 2nd Grade contains hundreds of activities, games, songs, storybooks, and characters to entertain your child for hours. With three full-featured CD-ROMs, it''s a great value. This software offers the TutorAssist technology to provide your child with personalized instruction that uses engaging multimedia tutorials.' FROM games WHERE igdb_id = 144365 ON CONFLICT (game_id, language_code) DO NOTHING;
