INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('harvest--2', 229365, '2002-12-31', NULL, NULL, 'https://images.igdb.com/igdb/image/upload/t_1080p/sckcru.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harvest', 'Harvest is a suspenseful mystery adventure game. This first game by the independent developer Michael B. Clark delves into the subconscious and paranormal. You are walking your dog in the park one night when he suddenly dashes off after something and disappears from sight. Searching for him, you find the entrance to an underground complex. Knowing your dog has gone into it, you follow and find yourself inside a huge bunker-like residence. Curiosity, plus the desire to find your pet, leads you further in. You uncover a madman''s plan involving a water extraction machine and the poisoning of the population''s water supply. The life of a once normal person was irrevocably changed with the death of his parents. What pushed him over the edge .. and where is your dog? The story develops as you read diaries, newspaper articles and other materials left behind. Secret rooms in the bomb shelter type area are protected by elaborate locks with puzzles connected to them. Puzzles are varied and include inventory-based ones, mechanical-logical Myst-style puzzles, a slider puzzle, memory puzzles and a maze. Graphics are mostly stills with little animation. There is mood-music and some sound effects can be heard. The game is mouse-controlled, point-and-click with various cursors for navigation and interacting with the environment.' FROM games WHERE igdb_id = 229365 ON CONFLICT (game_id, language_code) DO NOTHING;
