INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Golem', 'Released to various markets between 2002 and 2004, GOLEM is a real-time or optionally-turn-based strategy title from studio Longsoft Multimedia that follows a struggle between the changed remnants of humanity. The devolved United Clan, the evolved Genes, and the transcendent Cytex fight in the watery war theatre of flooded Sharmaris, Earth.' FROM games WHERE igdb_id = 345640 ON CONFLICT (game_id, language_code) DO NOTHING;
