INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Road Trip: Shifting Gears', 'Game Boy Advance multiplayer racing adventure game, released in Japan as "Choro Q Advance 2" and in Europe as "Gadget Racers". Road Trip: Shifting Gears continues the Takara-developed racing series on the GBA, and has the ability to link to Road Trip: Arcade Edition on the GameCube for unlockable extras. Players have full control over car customization, down to the most minute detail with a body paint shop, more than 100 different parts, and numerous fantasy attachments. Players compete in 150 racing events, minigames, in more than 64 courses. The game supports link cable connectivity for up to four players. In this release, Western localizations titles were swapped out, as North America rebranded into "Road Trip: Shifting Gears" (previously titled "Gadget Racers"), while Europe adopted the name "Gadget Racers" (previously titled "Penny Racers").' FROM games WHERE igdb_id = 49251 ON CONFLICT (game_id, language_code) DO NOTHING;
