INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars: The New Droid Army', 'Play as Anakin Skywalker against the evil Jedi master Count Dooku. Dooku attempts to create a powerful new droid army to assist him in his evil intentions. Anakin meets up with fellow Star Wars characters such as Queen Amidala, Yoda and Obi-Wan as he travels from his home planet, Tattooine, to the outer reaches of the galaxy. There are 9 stages as Anakin makes his way to a final battle with Count Dooku. Anakin becomes more experienced in the ways of the Force as the game progresses.' FROM games WHERE igdb_id = 6607 ON CONFLICT (game_id, language_code) DO NOTHING;
