INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Elite Forces: Navy SEALs', 'A new era of world conflict. Go where most men don''t dare and do what most men won''t. Arrive by sea, air and land prepared for unconventional warfare, counter-guerilla tactics and clandestine operations in the most turbulent hot spots in the world. Push your stamina and strength beyond your physical and mental limits, ready to lay down your life in service of your country.' FROM games WHERE igdb_id = 84183 ON CONFLICT (game_id, language_code) DO NOTHING;
