INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hunter: The Reckoning', 'Set in White Wolf''s World of Darkness, Hunter: The Reckoning lets you take the role of one of four different hunters--Deuce, a biker ex-con; Father Cortez, a prison chaplain; Kassandra, a raver chick; and Samantha, a tough ex-cop. Armed with a variety of fearsome weaponry--ranging from axes to shotguns--you''ll battle it out with hordes of supernatural enemies. Intense action combined with multiplayer support brings the true spirit of Hunter: The Reckoning to life.' FROM games WHERE igdb_id = 3950 ON CONFLICT (game_id, language_code) DO NOTHING;
