INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NBA Courtside 2002', 'Developed exclusively for Nintendo GameCube by Nintendo and Left Field, NBA Courtside 2002 taps into the power of Nintendo GameCube to deliver authentic NBA action that makes those other games look like they''re stuck in the era of the two-handed jump shot. Up to four players can hit the hardwood simultaneously and talk trash to their hearts'' content as they bust sweet cross-overs, first-step jukes and monster dunks.' FROM games WHERE igdb_id = 4031 ON CONFLICT (game_id, language_code) DO NOTHING;
