INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Search & Rescue 4: Coastal Heroes', 'It''s hard to improve on something great, but when the Coast Guard calls, you have to answer the challenge! Search & Rescue: Coastal Heroes is the newest installment of the successful Search And Rescue franchise, and is bringing you back into the fray as a heroic Coast Guard officer, entrusted with the daunting task of rescuing ordinary people caught in extraordinary circumstances.  Search & Rescue beginners and helicopter fans alike will love this latest creation in a classic series, that gets you as close to the real experience of flying Coast Guard rescue missions as you can, without actually sitting in the cockpit.' FROM games WHERE igdb_id = 50114 ON CONFLICT (game_id, language_code) DO NOTHING;
