INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Delta Force: Urban Warfare', 'Delta Force: Urban Warfare is a first-person shooter by developer and publisher NovaLogic. It was designed to be a military simulation loosely based on the Delta Force special operations force. The storyline spans twelve missions, including a bank robbery, hostage rescue, and an assault on an offshore oil rig.' FROM games WHERE igdb_id = 4134 ON CONFLICT (game_id, language_code) DO NOTHING;
