INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('xiao-xiao-no-6', 290868, '2002-01-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7vt6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scr362.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Xiao Xiao No. 6', 'Xiao Xiao No. 6 is the sixth installment in the Flash series Xiao Xiao, but only the third game. Like all previous installments, it once again consists of spectacular fight scenes featuring a black stickman. The initial part of Xiao Xiao No. 6 is a series of more or less non-interactive fight scenes, where the player must simply keep pressing Space to keep the animation going, with no penalty for delaying. In the next scene, the hero''s opponent is locked in a jail cell and the player''s goal is to click levers at the bottom to activate crushers in order to kill the prisoner; it''s not that easy because the prisoner is smart enough to avoid descending crushers. In the final scene, the player must press Space rapidly to fill a power bar before the time limit, so that the protagonist can deal a single powerful, finishing blow to his opponent; in the case of failure the player can immediately try again.' FROM games WHERE igdb_id = 290868 ON CONFLICT (game_id, language_code) DO NOTHING;
