INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yu-Gi-Oh! The Sacred Cards', 'In Yu-Gi-Oh! The Sacred Cards, it''s just as important to play your cards right as it is to get the right cards. This unique RPG gives you cards as weapons against the tough competition. You''ll battle in a tournament hosted by Kaiba Corporation and win the powerful Egyptian God Cards. Based on events from the Yu-Gi-Oh! animated TV series, The Sacred Cards offers hundreds of cards, over 100 duelists and rivals, and unexpected twists and surprises.' FROM games WHERE igdb_id = 6697 ON CONFLICT (game_id, language_code) DO NOTHING;
