INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bugdom-2', 94750, '2002-10-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6myy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3jp4.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bugdom 2', 'It has been three years since Rollie McFly rid the Bugdom of the evil King Thorax and his minions, but the Bugdom can still be a dangerous place as our new hero Skip is about to find out. While on his way to visit his family on the far side of the Bugdom, a Bully Bee swooped down and stole Skip’s knapsack. Your job as Skip is to track down the Bully Bee and get your knapsack back. The chase takes place mostly in and around a house. You will make new friends in the Bugdom who will help you through each area. Keep an eye out for Sam the Snail and Sally the Chipmunk. Sam will usually make you prove your worthiness before he will help you, but Sally is just interested in gathering acorns, so be sure to brings lots of those to her. Additionally, the same Buddy Bugs that helped Rollie McFly defeat King Thorax will help you defeat most mean enemy bugs that you encounter. Bugdom 2 is a 3D action-adventure game suitable for all ages.' FROM games WHERE igdb_id = 94750 ON CONFLICT (game_id, language_code) DO NOTHING;
