INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Riviera: The Promised Land', 'In Riviera: The Promised Land, you''ll follow two fierce warriors--each armed with godly weapons--in a mission to defeat demons once and for all. The adventure included lets you experience more than 30 hours of role-playing gameplay, complete with minigames, multiple endings, and secret paths and items. The game''s unique item system allows items to function differently depending on which characters equip them.' FROM games WHERE igdb_id = 6559 ON CONFLICT (game_id, language_code) DO NOTHING;
