INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rayman Bowling', 'A game released for mobile phones, a non-colour version releasing in 2002 followed by the colour version in 2003. Rayman Bowling is a simple bowling simulator featuring 11 different locations each one more difficult than the previous the levels being: the tutorial, classic, bridge, traps, carpet, rock, lava, panic, bomb, fire and bolt.' FROM games WHERE igdb_id = 106820 ON CONFLICT (game_id, language_code) DO NOTHING;
