INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Drome Racers', 'Tensions are high as you await the first stage of the Drome Championship.You''ve trained for the intensity of Multi-Challenge Racing; each race a seamless set of stages, mixing tracks from realistically stunning City, Mountain, and Canyon environments. Now you must prove you''re up to that grueling challenge. With high-tech racing machines based on new cars from the 2002 LEGO Racers construction toy range, Drome Racers is a racing experience like no other.' FROM games WHERE igdb_id = 3901 ON CONFLICT (game_id, language_code) DO NOTHING;
