INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('spyro-enter-the-dragonfly', 1579, '2002-11-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3qjh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scepxo.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spyro: Enter the Dragonfly', 'Spyro: Enter the Dragonfly is the fourth game in the Spyro the Dragon series and the first Spyro game to be on the PlayStation 2 and Nintendo Gamecube. Gameplay is similar to the previous three console games. The only playable character is Spyro, however he can man several vehicles: Hunter''s Manta Ray and the UFO''s make a return appearance from Year of the Dragon, alongside two new vehicles, the tank and the Spitfire attack plane. The game faced development issues that affected the final product, which resulted in being poorly made. Upon release, it was widely criticized for its numerous glitches, long loading times, and choppy framerate, with fans and critics calling it the worst entry in the franchise.' FROM games WHERE igdb_id = 1579 ON CONFLICT (game_id, language_code) DO NOTHING;
