INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('devilman-typing-soft-devil-strike', 141450, '2002-06-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2lkt.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8uqr.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Devilman Typing soft ~Devil Strike~', 'This software is a typing practice software that supports automatic recognition of Roman characters, based on the TV anime version "Devilman" that gained popularity in the 1970s. It is rare for typing software, and the images from that time are used as they are. The original version of the opening theme "Devilman''s Song" is also recorded, and the voice actors who are appearing are also members at that time. In "Story Mode", the demons sent by Demon King Zenon appear in the order of broadcasting. Let''s clear the stages one after another (by typing) while fighting as if you were the main character. In the "database", you can see character information, digested stories, and valuable setting materials. Of course, there is also a "training mode" for practice and dan certification to measure your current ability, so you can use it without getting tired of having fun or practicing seriously. Not only Go Nagai fans but also people of the age who were watching the broadcast at that time will be able to practice while feeling nostalgia. OS is compatible with Windows only. (translated from the amazon page)' FROM games WHERE igdb_id = 141450 ON CONFLICT (game_id, language_code) DO NOTHING;
