INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'JoJo no Kimyou na Bouken: Ougon no Kaze', 'JoJo no Kimyou na Bouken: Ougon no Kaze is an Action game, developed and published by Capcom, which was released in Japan in 2002. The game is based on the fifth story arc of Hirohiko Araki''s manga series JoJo''s Bizarre Adventure, Vento Aureo. Le Bizzarre Avventure di GioGio: Vento Aureo‍ ''​s graphics are similar to other cel-shaded games, like Jet Set Radio. The developer Capcom has utilized a game engine called "Artistoon" in order to create a graphical style similar to Araki''s art style in the manga.' FROM games WHERE igdb_id = 43465 ON CONFLICT (game_id, language_code) DO NOTHING;
