INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Virtua Striker 2002', 'The Virtua Striker series returns with 64 national football teams from around the world. Whether you play as France, Brazil, or Argentina, you can take your team to the final of the International Cup for a chance to win the trophy. On the road to the International Cup, you''ll encounter more than 1,400 different players with their own stats and play in 13 stadiums. Virtua Striker 2002 also includes player edit and replay functions.' FROM games WHERE igdb_id = 50567 ON CONFLICT (game_id, language_code) DO NOTHING;
