INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Higurashi no Naku Koro ni: Ch.1 Onikakushi-hen', 'On a certain day in June, someone dies, and someone else goes missing. The series of deaths is connected to the upheaval surrounding the dam construction project. A murder case that was covered up is being reenacted. Is it a conspiracy? A coincidence? Or perhaps a curse?' FROM games WHERE igdb_id = 248182 ON CONFLICT (game_id, language_code) DO NOTHING;
