INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Simpsons Skateboarding', 'The Simpsons Skateboarding is a sports video game where players have to skate in locations around Springfield. Nine characters are available to compete for the grand prize. Each character has over forty unique moves. Players can test their skills in either a two-player head-to-head skate off, or in one of the fast and furious modes: Freeskate, Skate Fest, Trick Contest, and a game of skateboard H-O-R-S-E, unlocking additional characters, locations, and skateboards.' FROM games WHERE igdb_id = 2843 ON CONFLICT (game_id, language_code) DO NOTHING;
