INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Age of Mythology', 'Age of Mythology is a real-time strategy game developed by Ensemble Studios and published by Microsoft Game Studios. Drawing inspiration from Greek, Egyptian, and Norse mythology rather than historical events, it diverges from the Age of Empires series while sharing familiar gameplay elements. The campaign follows Arkantos, an Atlantean admiral embarking on a journey through the lands of the game''s three cultures, hunting for a cyclops who is in league with Poseidon against Atlantis.' FROM games WHERE igdb_id = 324 ON CONFLICT (game_id, language_code) DO NOTHING;
