INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rugrats: Royal Ransom', 'Rugrats Royal Ransom is an action-adventure game released in 2002 by THQ for the PlayStation 2 and the Nintendo GameCube. The game is based on the Rugrats television series on Nickelodeon. The game''s plot is loosely based on Rugrats: Castle Capers.' FROM games WHERE igdb_id = 2793 ON CONFLICT (game_id, language_code) DO NOTHING;
