INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rhem', 'Rhem is an adventure game in which the player explores a barren, maze-like landscape of water ponds, walkways, and brick buildings with the aid of a partial map. The game has several puzzles involving machines and symbols.' FROM games WHERE igdb_id = 22758 ON CONFLICT (game_id, language_code) DO NOTHING;
