INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LEGO World Builder', 'World Builder is a Shockwave puzzle-platformer that was hosted on the official LEGO website in 2002. The player must collect LEGO pieces and the recipes that allow them to assemble those pieces into different kinds of units and vehicles. Each unit type has its own capabilities, allowing the player access new areas and collect more pieces and recipes.' FROM games WHERE igdb_id = 243462 ON CONFLICT (game_id, language_code) DO NOTHING;
