INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spyro: Year of the Dragon - Collector''s Edition', 'The Collectors'' Edition version of Spyro: Year of the Dragon. This game is part of a trilogy released in the Spyro Collectors'' Edition boxset. This version is mostly the same as the original. The only key difference is the words "Collectors'' Edition" on both the disc and manual. The manual also has a white Playstation banner instead of the typical black banner.' FROM games WHERE igdb_id = 43684 ON CONFLICT (game_id, language_code) DO NOTHING;
