INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dooms', 'Dooms is a serial killer simulator made in RPG Maker 2000. On a rainy night, a man named Bob catches his wife cuckolding him in bed with another man and, driven by rage, kills them both. Over 30 years later, he escapes from prison and, together with his new partner Jack who disguises as a clown, they begin a brutal killing spree. Two versions of this game exist, the original one from 2002 that was lost until 2022 and another one almost made from scratch in RPG Maker 2003 in 2010.' FROM games WHERE igdb_id = 340999 ON CONFLICT (game_id, language_code) DO NOTHING;
