INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shrek Treasure Hunt', 'Players control Shrek on a quest to find ten missing picnic items stolen by the Three Blind Mice. The result is an adventure through ten different locales linked together by the swamp. Players guide Shrek from a third-person perspective as they avoid mischievous swamp critters trying to stun them. Each area contains a mini-game that will reveal one of the lost picnic items once completed. The catch? Shrek must first collect a specific number of items to gain access to the mini-game.' FROM games WHERE igdb_id = 44967 ON CONFLICT (game_id, language_code) DO NOTHING;
