INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grand Theft Auto: Vice City', 'In the year 1986, Tommy Vercetti is heavily indebted to his mafia superiors after a drug deal gone awry, but his dreams of taking over Vice City (based on Miami) push him down a different path. Featuring a wide variety of vehicles and weapons, radio stations playing hit songs from the era and an intense atmosphere, GTA: Vice City is an open-world sandbox satire of ''80''s Miami.' FROM games WHERE igdb_id = 733 ON CONFLICT (game_id, language_code) DO NOTHING;
