INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World Soccer Winning Eleven 6: Final Evolution', 'World Soccer Winning Eleven: 6 Final Evolution is an updated version of the base game and was released for Sony PlayStation 2 and Nintendo Gamecube. World Soccer: Winning Eleven 6 Final Evolution features six game modes, including single matches, training, various cup tournaments, and a Master League, in which the player can select a team to compete in various competitions and partake in the transfer market. A total of 40 unlicensed club teams and 56 unlicensed international squads (except for Japan, which is the only fully licensed team in the game) are available.' FROM games WHERE igdb_id = 14733 ON CONFLICT (game_id, language_code) DO NOTHING;
