INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('shin-megami-tensei-if-dot-dot-dot--1', 270672, '2002-12-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co778n.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scvqhe.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shin Megami Tensei if...', 'Like the first two entries in the Shin Megami Tensei series, the spin-off with the mysterious title If... got its own remake. As in the other two cases, the graphics of the remade version have been redone from scratch, to match the 2D standard of 32-bit generation consoles. Interior locations are much more detailed, with visible furniture and other items in rooms that were empty or contains just a few objects in the original version. The 3D dungeons can now be navigated with smooth scrolling, unlike the "jumping" navigation of the earlier versions. The remake also has an additional difficulty level, dubbed "normal"; the original difficulty level is called "hard". The easier difficulty level also reduces the amount of random battles. Story, dialogues, layout of locations, and general gameplay remain unchanged in this version.' FROM games WHERE igdb_id = 270672 ON CONFLICT (game_id, language_code) DO NOTHING;
