INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Earth and Beyond', 'Earth and Beyond is a science fiction MMORPG set in a future where three human-descended races—Terrans, Progen, and Jenquai—control different regions of space. The Terrans dominate Earth through powerful trade corporations; the Progen, genetically engineered for strength and efficiency, inhabit Mars; and the Jenquai, focused on knowledge and exploration, occupy space stations orbiting Jupiter’s moons.' FROM games WHERE igdb_id = 23764 ON CONFLICT (game_id, language_code) DO NOTHING;
