INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World Soccer: Winning Eleven 6 International', 'Pro Evolution Soccer 2, known as World Soccer: Winning Eleven 6 in Japan, is the second instalment of Konami''s Pro Evolution Soccer football video game series. The Japanese version was succeeded by the updated World Soccer: Winning Eleven 6 Final Evolution. It was the last game of the series released in Europe for PlayStation and the only game released for the Nintendo Gamecube.' FROM games WHERE igdb_id = 4643 ON CONFLICT (game_id, language_code) DO NOTHING;
