INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('fire--6', 231721, '2002-10-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co618m.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar22zy.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fire', 'Mario and Luigi attempt to catch Toads, Yoshis, and Donkey Kong Jrs. after they jump out the window of Princess Peach''s burning castle. The catch is that different characters fall at different speeds: Toads bounce the highest, while Donkey Kong Jrs. bounce the lowest. Yoshi Eggs also appear and contain either a Bob-omb or a Moon (a Super Star in the first game); the eggs break open when they are caught or hit the ground. The player receives two points for catching an egg. If a Bob-omb reaches the carriage, everyone, including the Mario Bros., runs away as the carriage explodes, and the player gets a miss. If the Mario Bros. catch a Moon, the player receives five points. At 200, 500, and 700 points, Peach appears and blows a kiss, sending out a heart for Mario or Luigi to catch to remove a miss. Music is also featured in this version, with the tempo changing depending on the speed of the game. In the Game & Watch Gallery 4 version, the time of day changes every 200 points collected. If the player selects this game in Game & Watch Gallery 4 yet does not start playing it, a humorous sequence plays. In particular, Mario and Luigi catch a Toad sent flying to the left and a Yoshi sent flying to the right, only to narrowly stop when discovering their next "rescue" was in fact a Bob-omb, which detonates inches from them, and are then forced to flee as a dozen Bob-ombs are raining from the sky.' FROM games WHERE igdb_id = 231721 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 231721 AND ge.slug = 'arcade' ON CONFLICT DO NOTHING;
