INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ShenSonic', 'ShenSonic is a fan game made by SimSonic, whose real name is Simon Elo, of Magitek Soft which has also created the Sonic in Mobius games. This fan game was previously created using The Games Factory but the final version used Multimedia Fusion Express. ShenSonic is Shenmue but with Sonic characters and makes changes to the plot to fit the Sonic universe. It features 100+ characters, 4 locations, 8 mini-games, day and night cycle, QTE''s, inventory system, and much more.' FROM games WHERE igdb_id = 246722 ON CONFLICT (game_id, language_code) DO NOTHING;
