INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sega Bass Fishing Duel', 'Put on fishing caps, fill up the coolers, and get ready to play the game that is just like life on the lake. This is the third title in the SEGA Bass Fishing series. Choose a character from a cast of anglers, each with their own distinct and unique characteristics. Fish on lakes that reflect the seasons, time of day, temperature, weather, and wind. With practice, tournament, versus modes, and great graphics, SEGA Bass Fishing Duel is a great sporting-adventure!' FROM games WHERE igdb_id = 22231 ON CONFLICT (game_id, language_code) DO NOTHING;
