INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('robot-alchemic-drive', 24083, '2002-08-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co57ar.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8qit.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Robot Alchemic Drive', 'Robot Alchemic Driver is a Big Robot/Monster fight in a modern city with a twist. There is a story and training mode and a 2 player vs. mode. In a nut shell, alien''s attack the last city on earth. The big robot comes up, and here is where the twist come in, you have to control the robot from the perspective of the "hero" (three to choose from) and you can switch between the robot/hero mode. This forces you to make sure you have a strategic position to move the hero around in the city to see the battle without getting too close. As the game goes on you have the option to update/customize the mech(s) to improve them. You can end up destroying whole building/terrain as you battle the alien monster.' FROM games WHERE igdb_id = 24083 ON CONFLICT (game_id, language_code) DO NOTHING;
