INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dino Stalker', 'Dino Stalker is a horror light gun shooter video game developed exclusively for the PlayStation 2. It is an offshoot of the Resident Evil light gun shooter games, but based on the story of the Dino Crisis series. Though it can be played by other means, a light gun is recommended, as the game is one in a number of Capcom games that try to bridge the gap between light gun games and traditional games that allow the player greater range of control over their movements in the game.' FROM games WHERE igdb_id = 22065 ON CONFLICT (game_id, language_code) DO NOTHING;
