INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dark-planet-battle-for-natrolis', 23457, '2002-03-21', 56, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3izh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ixmfyyifkxebiz2cwxel.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Planet: Battle for Natrolis', '3 unique races to play with different strategies for success: Colonists - High Tech (a sci-fi mechanized army), Sorin - Swords and Sorcery (a fantasy army with magic powers), Dreil - Monsters (use brute force and hive and cocooning behavior) Highly detailed 3D world with day and night cycles, plants that sway in the wind, and ambient creatures that have their own life cycles and AI. Realistic weather that effects your strategy. Rains will slow down movement, wind patterns change, nighttime brings darkness. True 3D engine with fully adjustable perspective, zoom, and viewing angle. Classic RTS Gameplay with brand new concepts. Easy to learn, but a challenge to master. Multiplayer options with several different modes, including Domination, Capture the Flag, and Campaign.' FROM games WHERE igdb_id = 23457 ON CONFLICT (game_id, language_code) DO NOTHING;
