INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Family Crisis', 'Family Crisis is a puzzle game where you help a family cross a dangerous path at night. Each person has a different walking speed, and you can only move two people at a time with a lamp. The goal is to get everyone across safely in the shortest time possible. It’s a game of strategy and planning.' FROM games WHERE igdb_id = 381386 ON CONFLICT (game_id, language_code) DO NOTHING;
