INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'No Limite', 'No Limite is a survival sim based on the reality show by the same name, developed by Continuum and published by Brasoft in collaboration with Rede Globo. Be one of the twelve participants of the virtual No Limite and live days of great emotion! Make part of the Sol team or the Lua team and socialize with the other participants. Meet the other participants to vote in the Portal of the 4 Elements. But beware! The audience is watching everything and you may be eliminated.' FROM games WHERE igdb_id = 140882 ON CONFLICT (game_id, language_code) DO NOTHING;
