INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('touhou-koumakyou-the-embodiment-of-scarlet-devil', 27155, '2002-08-11', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co268s.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc88ku.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Touhou Koumakyou: The Embodiment of Scarlet Devil', 'Embodiment of Scarlet Devil features two playable characters to choose from, with two Spell Card types each. Reimu Hakurei can cover a wide area of the screen with weaker attacks, while Marisa Kirisame relies on her speed and power to make up for her thinner attack spread. The bombs show different behavior and damage depending on the character and type chosen. Unlike its predecessor, Mystic Square, Embodiment of Scarlet Devil comes with an "automatic item collection" feature, which allows you to collect all items on the screen by moving to the top of the screen if you are at full power, as well as a counter-bomb system, which allows you to avoid a fatal hit by using a bomb immediately. Though there are six total stages in the main game, playing on Easy will end the game after Stage 5.' FROM games WHERE igdb_id = 27155 ON CONFLICT (game_id, language_code) DO NOTHING;
