INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dropship-united-peace-force', 44723, '2002-07-11', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8ha4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/schm1n.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dropship: United Peace Force', 'Dropship is an action game set in the year 2050. Terrorist attacks have increased severely, which is why big nations of the world decided to form the UPF, "United Peace Force", replacing the UN and NATO. It is an anti-terror army, operating world-wide. But there is another globally operating group: A massively militarised drug syndicate. When an attack on a peace convoy in Columbia is linked to this cartel, the UPF starts investigation. A central base and training camp of the drug cartel is believed to be located somewhere in Libya. The UPF opens up a base in this country and starts looking for the criminals. The player is a recently recruited soldier and pilot of the UPF. During the campaign, which lasts for 20 rather long missions, he can travel and fight on foot, in tanks and various other ground vehicles, but most of the time he will be piloting a dropship, either of the attack, defender or transport class. Dropships can operate in hover and flight mode, and carry a large amount of weapons and cargo.' FROM games WHERE igdb_id = 44723 ON CONFLICT (game_id, language_code) DO NOTHING;
