INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metroid Prime', 'A 3D exploration-focused metroidvania with first-person shooting mechanics and the first 3D entry in the Metroid series, Metroid Prime follows Samus Aran after the events of Metroid (1986) as she boards a Space Pirate frigate, then chases her escaping archrival Ridley into the intricately structured Tallon IV, a planet full of deadly wildlife and former home to the advanced and ancient Chozo race.' FROM games WHERE igdb_id = 1105 ON CONFLICT (game_id, language_code) DO NOTHING;
