INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BattleBots: Beyond the BattleBox', 'Welcome to BattleBots, the sport of remote-controlled robotic combat. Based on the popular television series, you build your own customized, radio-controlled robots that employ an array of destructive weaponry such as hammers, saws and spikes. Watch the sparks fly as you duke it out in deadly arenas against your friends or one of the 16 actual BattleBots from the T.V. show. This is the ultimate contest of strategy and creativity where the goal is survival.' FROM games WHERE igdb_id = 6320 ON CONFLICT (game_id, language_code) DO NOTHING;
