INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chocobo Land: A Game of Dice', 'Dice de Chocobo is a video game originally released in 1999 for the PlayStation in the Chocobo Collection. It was later planned to be remade for the WonderSwan Color, but was cancelled, and it was finally remade for the Game Boy Advance in 2002 and given the title Chocobo Land: A Game of Dice.' FROM games WHERE igdb_id = 49559 ON CONFLICT (game_id, language_code) DO NOTHING;
