INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Junkbot Undercover', 'The sequel to Junkbot. It is a Shockwave puzzle-platformer that was hosted on the official LEGO website in 2002. The player must place LEGO bricks to form paths and stairways so Junkbot can reach and consume all the recycling bins in a level. The game introduces lasers as a new hazard, as well as various other new elements such as moving blocks and teleportation pads.' FROM games WHERE igdb_id = 244005 ON CONFLICT (game_id, language_code) DO NOTHING;
