INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Barbie: Sparkling Ice Show', 'Join Barbie and friends on her spectacular world tour as she performs dazzling ice skating maneuvers in cute costumes that you can select yourself. On your way to ice-skating super stardom, you can join the tour or skate through the game at your own pace. All aspects of Barbie''s skating escapades are fully customizable - you can design your own routines and select music and outfits. Girls of all ages will have hours of fun with Barbie and her friends.' FROM games WHERE igdb_id = 57592 ON CONFLICT (game_id, language_code) DO NOTHING;
