INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World War Zero', 'The World War began in August 1914. It is now March 1964, and war still wages on. The Russian October Revolution has taken place, but the Bolsheviks were crushed by the mad Baron Ugenberg. He plans to build a huge Russo-Mongolian empire that stretches from the Atlantic to Vladivostok, crushing any opposition in his wake.' FROM games WHERE igdb_id = 127176 ON CONFLICT (game_id, language_code) DO NOTHING;
