INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('melty-blood', 72858, '2002-12-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3d6k.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/so1adcsnt6rwubwsskdc.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Melty Blood', 'Tohno Shiki hears of a new series of murders in Misaki similar to the ones that took place in Tsukihime. Whilst searching for the murderer he meets Sion Eltnam Atlasia who initiates a fight with him, attempting to capture him. After the fight she reveals that her reason for attempting to capture him is to get in contact with the "True Ancestor" (referring to Arcueid) so that she may acquire information on the "cure for vampirism". Shiki then decides to help her with this task. The sequel to the visual novels Tsukihime and Kagetsu Tohya, Melty Blood is a combination visual novel/fighting game. The story moves through a series of fights. Depending on the outcome of each fight, the story will branch in one of two ways. Ultimately this corresponds to the ending of the game. The first couple of PC releases had adventure style stories with branches and multiple number of endings and a secondary story in arcade mode. Later versions only have the arcade mode, but they have many more characters.' FROM games WHERE igdb_id = 72858 ON CONFLICT (game_id, language_code) DO NOTHING;
