INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Funshiki', 'Funshiki is a 3D action game where you control a rocket-powered box sliding over a frictionless surface, much like ice skating. The game is heavily based on inertia and momentum. You must carefully manage your thrust using rocket engines on the front and back of the box to move, stop, or turn. The objective on each stage is to collect all the gems while avoiding walls and obstacles.' FROM games WHERE igdb_id = 340032 ON CONFLICT (game_id, language_code) DO NOTHING;
