INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('overpower-rpg-capitulo-1-a-saga-de-bulgar', 348733, '2002-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9yam.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scxcvy.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Overpower RPG - Capítulo 1: A Saga de Bulgar', 'Overpower is a Brazilian game developed on RPG Maker 2000, originally released in 2002 and developed by E.F.N. Most of its assets come from the Runtime Package (RTP), and its sense of humour is typical of the early 2000s Brazilian internet. Despite that, the game had high narrative and gameplay ambitions. You start the game by choosing one out of four characters. Each character has its own narrative line, and their stories eventually cross each other. The game also has an alignment system that, although simple, can have surprising consequences. For example, depending on the circumstances of your death, instead of a game over your party can be sent to either heaven or hell, where there''s an opportunity to be brought back to life, for a price. The game also features an extensive magic system, with 11 different Schools of Magic. According to the "LEIA-ME!!!" file, Overpower: A Saga de Bulgar was supposed to be the first of at least three chapters. The other two were tentatively titled "A Saga de Dark Elf" and "A Vingança do Rei Dragão". There were also plans to let players transfer their save files between chapters. Despite its ambitions, Overpower has yet to receive a sequel.' FROM games WHERE igdb_id = 348733 ON CONFLICT (game_id, language_code) DO NOTHING;
