INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Baku Funshiki', 'Baku Funshiki is a hard-mode sequel to the game Funshiki. It features 10 extremely challenging stages, far more difficult than the original. The core gameplay remains the same: controlling a rocket-powered box on a frictionless surface using inertia-based mechanics to collect items and avoid obstacles.' FROM games WHERE igdb_id = 340033 ON CONFLICT (game_id, language_code) DO NOTHING;
