INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tantei Jinguji Saburo: Innocent Black', 'The 8th installment of the Tantei Jinguuji Saburo series, and the first to be developed by WorkJam. Jinguuji is asked to search for a missing daughter from the director of a hospital where he had received treatment. This small case gradually expands to revive a deep and complex mystery.' FROM games WHERE igdb_id = 77057 ON CONFLICT (game_id, language_code) DO NOTHING;
