INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metroid Fusion', 'The famed Metroid series makes its return on the Game Boy Advance with Metroid Fusion. After Samus'' exploits in the Super Nintendo classic Super Metroid, the intergalactic bounty hunter becomes infected with a parasitic life form known only as "X". Samus is rescued and revived by Metroid DNA only after undergoing some major changes in her body and suit, resulting in a drastic change in her appearance, and a new ability to absorb and assimilate the abilities of the "X" virus. Experience a new and enthralling chapter in the Metroid series, and relive the timeless gameplay and exploration that made the series a legend.' FROM games WHERE igdb_id = 1104 ON CONFLICT (game_id, language_code) DO NOTHING;
