INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Scooby-Doo! in the Ghosts of Pirate Beach', 'Scooby-Doo! in the Ghosts of Pirate Beach is a browser-based adventure and puzzle game released in 2002 by Cartoon Network. In this game, the Mystery Inc. gang is called to Pirate Beach to investigate ghost pirates who are terrorizing tourists and have kidnapped archaeologists searching for the treasure of Redbeard.' FROM games WHERE igdb_id = 141457 ON CONFLICT (game_id, language_code) DO NOTHING;
