INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ty the Tasmanian Tiger', 'G''day, Mate. Explore the wilds of Australia with TY the Tasmanian Tiger, the charming Aussie platformer. Stone the crows! Are you ready to explore the wilds of the Australian Outback in this remastered version of the classic game, TY the Tasmanian Tiger? Join TY on a ripper of an adventure to free his family from the dreaming and stop the nefarious evil genius boss cass from removing mammals from the top of the food chain. To help you on your quest, you''ve got a beaut arsenal of boomerangs, sharp teeth, and the help of a few friends!' FROM games WHERE igdb_id = 1322 ON CONFLICT (game_id, language_code) DO NOTHING;
