INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nhl-2k3', 4045, '2002-11-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2hmq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scsvb6.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NHL 2K3', 'NHL 2K3 is a hockey video game developed for the GameCube, PlayStation 2, and Xbox by Treyarch and published by Sega in the United States, and Atari in Europe. It features Jeremy Roenick on the cover. NHL 2K3 utilizes ESPN''s presentation and was the first hockey game developed to utilize the Xbox Live online service. The rosters are from the 2002–2003 NHL season.' FROM games WHERE igdb_id = 4045 ON CONFLICT (game_id, language_code) DO NOTHING;
