INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Knight Rider: The Game', 'Knight Rider: The Game is a video game developed by Davilex Games based on the original television series of the same name. The game was released in Europe on PlayStation 2 and PC on November 22, 2002 and in North America on the PC on February 12, 2003. The game allows the player to take control of KITT - the Knight Industries Two Thousand, in a range of missions including, racing, exploring, chasing and others. The player will also meet famous villains from the original series, including KARR and Garthe Knight.' FROM games WHERE igdb_id = 22369 ON CONFLICT (game_id, language_code) DO NOTHING;
