INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RollerCoaster Tycoon 2', 'Stretch your imagination further to build bigger parks and higher coasters! Break ground and start from scratch, open the gates to a remarkable Six Flags park, or just create the most gut-wrenching roller coaster imaginable - now you can play your way! Choose and complete different scenarios accordingly to the experience and content you like. Satisfy the visitors by building various attractions and facilities.Wild new rides, exciting new themes, and improved easy-to-use building tools make creating the ultimate amusement park more fun than ever!' FROM games WHERE igdb_id = 331 ON CONFLICT (game_id, language_code) DO NOTHING;
