INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Air Ranger Rescue Helicopter', 'An exciting challenge for all budding aviators, Air Ranger Rescue Helicopter puts you in the role of Kane, a dedicated rescue pilot. Four enormous stages and eight types of rescue are on offer as you - and your brave colleagues, Bob, Matilda and Ivan - try to avert disaster and save the day. From evacuating runaway trains to extinguishing an inferno from the air, you will be stretched to your limit in this exciting helicopter sim.' FROM games WHERE igdb_id = 46036 ON CONFLICT (game_id, language_code) DO NOTHING;
