INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pac-Xon Hero Strikes Back!', 'Your goal is to fill the empty space and capture the monsters by building a wall around them. You can advance to the next level once 80% of the space is filled. Don''t let the monsters touch you, and try to get the power-ups that appear randomly around the screen.' FROM games WHERE igdb_id = 238859 ON CONFLICT (game_id, language_code) DO NOTHING;
