INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Resident Evil Assault the Nightmare', 'BIOHAZARD A.T.N. ASSAULT THE NIGHTMARE is a video game in the Resident Evil franchise. It was released in 2002 for NTT DoCoMo''s 504 and 505 phones in Japan. It was sold as part of a subscription to ''Capcom Party'' at ¥350 per month. Later, the game was adapted for western mobile phones as well. Following talks with European phone operators, Capcom released the game internationally in mid-2004 under the title, "Resident Evil Assault the Nightmare".' FROM games WHERE igdb_id = 356222 ON CONFLICT (game_id, language_code) DO NOTHING;
