INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mega Man Zero', 'It''s your mission to help the exiled scientist Ciel discover the source of a new reploid energy! Play as Mega Man''s pal Zero, the reploid from the Mega Man X series turned good by the infectious Sigma Virus and 100 years of sleep. Conquer your adversaries and find the energy source... or risk ultimate defeat. It''s up to you to defend good from the destructive powers in the universe.' FROM games WHERE igdb_id = 1775 ON CONFLICT (game_id, language_code) DO NOTHING;
