INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gran Turismo Concept: 2002 Tokyo-Seoul', 'A second version of Gran Turismo Concept, 2002 Tokyo-Seoul, was released in South Korea on May 16th, 2002, to celebrate the PlayStation 2 official launch in this country. It featured cars from the 2001 Tokyo version plus additional models unveiled at the Seoul Motor Show. This game introduced South Korean automakers, like Hyundai, in the Gran Turismo series. As of April 2008, Gran Turismo Concept 2002 Tokyo-Seoul has shipped 90,000 copies in South Korea.' FROM games WHERE igdb_id = 73022 ON CONFLICT (game_id, language_code) DO NOTHING;
