INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Emogame 1: A Get-Up Kidnapping!', 'The emo band "The Get-Up Kids" gets kidnapped by Steven Tyler to be sodomized in his dungeon, and a group of Emo rockers set out to save them, going on an adventure through Suburbia, MTV Studios and Steven Tyler''s dimension of evil that reveals the true origin of emo kids.' FROM games WHERE igdb_id = 358403 ON CONFLICT (game_id, language_code) DO NOTHING;
