INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rhino-rumble', 49947, '2002-04-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co48zv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar20co.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rhino Rumble', 'It''s amazing what some animals will do just to get a drink of water. Take Rocky the Rhino, for instance: Positively parched (he ate way too many peppers at a local jungle party), the little fellow is willing to traverse 19 enormous levels in the hope of quenching his mighty thirst. Help the adorable Rocky get through seven unique worlds, fending off all who would stand in his way. Many of the jungle''s inhabitants are convinced that Rocky will drink up the water supply, you see, so they''re all working against you from the outset. Make your way through forests and caves, using unique artillery like fireball breath and belly jumps to squelch the attempts of your foes and get to the magical spring. In addition to your weaponry, you''ll have the assistance of various boats, planes, trampolines, and wagons to reach the end of each level.' FROM games WHERE igdb_id = 49947 ON CONFLICT (game_id, language_code) DO NOTHING;
