INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'One Piece: Treasure Wars', 'One Piece: Treasure Wars is an Action game, developed by Graphic Research and published by Bandai, which was released in Japan in 2002. In the game, the player chooses one of the Straw Hat Pirates and fights other members of the crew in the board game. The main goal is for the player to find the treasure or special item before his opponent does. Each player will run around the board fighting against other pirates. The members of the crew the player did not choose as his or her character will also be running around along with other enemies who the crew has to fight.' FROM games WHERE igdb_id = 37447 ON CONFLICT (game_id, language_code) DO NOTHING;
