INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sanguo-zhao-yun-zhuan-zhi-zongheng-tianxia', 351352, '2002-09-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa1s1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scxqdh.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sānguó Zhào Yún Zhuàn Zhī Zònghéng Tiānxià', 'San Guo Zhao Yun Zhuan Zhi Zong Heng Tian Xia is the sequal of San Guo Zhao Yun Zhuan, a game based on popular historical figure Zhao Yun during The Three Kingdom period in Chinese history. It is an action RPG which highlights Zhao Yun’s military career, filled with daring charges and hard-fought victories. Compared to the previous title, the combat system has undergone major upgrades: battles now unfold as large-scale clashes involving multiple factions. Iconic military strategies once confined to books or real-life history — from siege warfare and rescue operations to breakouts, night raids, and psychological tactics — are now fully integrated into the gameplay. Both in terms of scale and intensity, the action is far more ambitious than before. No longer is the battlefield just a place for chaotic button-mashing; intelligence and strategy are just as important as raw strength. Every decision the player makes influences the course of the game, shaping not only how battles unfold, but also how the story is written.' FROM games WHERE igdb_id = 351352 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 351352 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
