INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monsters, Inc.: Pinball Panic', 'This game is part of the Wreck Room Arcade series which consists of four different "activities". You can buy and play them separately, but they link into the same main menu - and, if you have bought them all, you get another bonus game for free (it will be unlocked after you''ve installed the last game). This is a simple pinball game with a Monsters Inc. theme.' FROM games WHERE igdb_id = 68735 ON CONFLICT (game_id, language_code) DO NOTHING;
