INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stuntman', 'In the world of stunt driving, all it takes is one slip to end your Hollywood dreams. As a stunt driver, you can''t afford to fail when performing dangerous stunts. In six famous movie locations, you''ll smash up vehicles ranging from TukTuks and snowmobiles to Jeeps and high-performance sports cars. Begin a career in the stuntman industry or practice your skills in the stunt arena. After another hard day of risky work, replay the action as a polished movie trailer.' FROM games WHERE igdb_id = 8267 ON CONFLICT (game_id, language_code) DO NOTHING;
