INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Drift: When Worlds Collide', 'In the distant future, the Dorian Empire invades the Hen-Shodan Republic for their resources. The Hen-Shodan have hired the toughest and nastiest mercenary pilots around to face the Dor -- and you''re one of them! Choose from five different strike fighters and face off against your enemies in 28 deadly missions Run reconnaissance, go on search & destroy flights, and get into serious combat with massive motherships Select from 17 different weapons of mass-destruction, and 8 different shields for self-defense Dynamic graphics bring space combat to life in this wild space opus!' FROM games WHERE igdb_id = 71505 ON CONFLICT (game_id, language_code) DO NOTHING;
