INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Stitch: Experiment 626', 'The game takes place before the Lilo & Stitch film begins, showing the massive space universe only hinted at in the movie. The player controls Stitch, using his powers to the fullest: climbing walls and ceilings, dashing with amazing speed, shooting up to four weapons at once (one in each hand), flying with the jetpack, and swinging using the grapple gun. The game features several of the film''s memorable characters, including Jumba, Gantu, and Grand Councilwoman.' FROM games WHERE igdb_id = 25911 ON CONFLICT (game_id, language_code) DO NOTHING;
