INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('icewind-dale-ii', 876, '2002-08-27', 86, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1t8o.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8gqc.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Icewind Dale II', 'Icewind Dale II is a captivating role-playing game developed by Black Isle Studios, released in 2002 as the sequel to the acclaimed Icewind Dale. Set in the Forgotten Realms universe of Dungeons & Dragons, the game thrusts players into the harsh, frozen landscapes of Icewind Dale, where they lead a party of adventurers against a looming evil threat. Utilizing an improved version of the Infinity Engine, Icewind Dale II offers enhanced graphics and a more user-friendly interface, while implementing 3rd Edition D&D rules that expand character creation options with new races and classes. The game is celebrated for its challenging combat encounters, intricately designed dungeons, and a gripping narrative that intertwines themes of invasion, betrayal, and ancient magic. While maintaining the series'' focus on combat and exploration, Icewind Dale II introduces more substantial character interactions and side quests, enriching the role-playing experience. The real-time with pause combat system allows for deep tactical gameplay, appealing to strategy enthusiasts. With its blend of expansive character customization, immersive storytelling, and strategic depth, Icewind Dale II stands as a beloved entry in the classic CRPG genre, offering a rewarding experience for both series veterans and newcomers alike.' FROM games WHERE igdb_id = 876 ON CONFLICT (game_id, language_code) DO NOTHING;
