INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NBA Live 2003', 'The 2003 version of the NBA simulator has improved graphics in relation to the previous installments and features like detailed faces and a player design engine. It also has rosters in accordance to the 2002-2003 Season. The game features more than 30 new rebound animations worked out by motion capture sessions, different passing styles and blocks and a frame rate of 60 frames per second. As usual, a complete fantasy draft is included and multiplayer support is present.' FROM games WHERE igdb_id = 808 ON CONFLICT (game_id, language_code) DO NOTHING;
