INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('superlite-1500-series-battle-qix', 370501, '2002-10-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob3nr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4ymj.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SuperLite 1500 Series: Battle Qix', 'Qix was an arcade game, released by Taito America Corporation in 1981. The objective of Qix is to fence off, or “claim”, a supermajority of the playfield. At the start of each level, the playing field is a large, empty rectangle, containing the Qix — a sticklike entity that performs graceful, but unpredictable motions within the confines of the rectangle. The player controls a small diamond-shaped marker that can move around the edges of the rectangle, with the goal to claim as much of the screen as possible via drawing Stix. When the player completes a closed shape, the captured area becomes solid and points are awarded. To complete a level, the player must claim most of the playfield. (The game was shipped at 75 percent, but the arcade operator could adjust the requirement between 50 percent and 90 percent.) The player has a limited number of lives and can lose a life if the Qix touches a Stix line as it is being drawn, or by being touched by Sparx - enemies that traverse all playfield edges except uncompleted Stix. Additionally, a Fuse appears if the marker stops moving whilst in the process of drawing Stix, disappearing when the player starts moving again. The player has no ability to defend themselves, and all enemies must be outmaneuvered. A Time Meter located at the top of the screen is responsible for the countdown of the entry of additional Sparx and the mutation of all Sparx to Super-Sparx, which have the ability to chase the player even up an unfinished Stix line. After the player completes two levels, the difficulty increases. This includes multiple Qixes and Sparxes, speed increases, and the eventual appearance of only Super Sparxes. Superlite 1500 Series - Battle Qix is the latest game in the Qix series, and it was only released on the Playstation console.' FROM games WHERE igdb_id = 370501 ON CONFLICT (game_id, language_code) DO NOTHING;
