INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Coloball 2002', 'Coloball 2002 is a turn-based strategy role-playing video game for the PlayStation 2. The game was developed by Vanpool and published by Enterbrain exclusively in Japan on June 27, 2002. The title Coloball is short for "Colosseum Ball," and although the game is touted as a sports adventure game, it is most similar to an RPG board game.' FROM games WHERE igdb_id = 91681 ON CONFLICT (game_id, language_code) DO NOTHING;
