INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('boxing--5', 231744, '2002-10-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co618f.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar22yu.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Boxing', 'The Modern version of the game features Luigi as a playable character. This version has three opponents: a Wiggler, a Big Boo, and Waluigi. Luigi has to beat all his opponents. After that, he has to repeat the fighting order along with winning a coin, a trophy, or a Championship Belt. Luigi and his opponents start with five hit points each, and they reset to five each time one of them gets pushed back. As the player advances in the game, the enemies get more difficult to defeat. Getting one KO earns a coin, getting five earns a Yoshi Coin, getting ten earns a trophy, and getting 50 earns a Championship Belt. It is Game Over if Luigi gets KO''d.' FROM games WHERE igdb_id = 231744 ON CONFLICT (game_id, language_code) DO NOTHING;
