INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tokyo Majin Gakuen: Gehoujou', 'As with the tradition of Tokyo Majin Gakuen franchise, Tokyo Majin Gakuen: Gehoujou is an adventure/strategy RPG hybrid. In adventure mode, players interacts with characters for answers. Affecting the answers and overall story progression are nine "emotions": love, friendship, joy, agreement, sorrow, anger, indecision, scorn, and ignorance. In battle mode, the party fights on isometric battle screens, moving around the battlefield and attacking when enemies are in range.' FROM games WHERE igdb_id = 91926 ON CONFLICT (game_id, language_code) DO NOTHING;
