INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ring-ii-twilight-of-the-gods', 73656, '2002-09-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co98ra.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scqknh.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ring II: Twilight of the Gods', 'Twilight of the Gods is the second installment continuing Richard Wagner''s opera about the Ring of the Nibelungen, based upon Nordic mythology and works of the brothers Grimm, and features his original music. The player is the main character, Siegfried, who is called upon by Wotan, the king of the gods, to fulfill his destiny. In this segment, Siegfried will boldly challenge the gods of power themselves and ultimately cause the end of their reign. There are significant interface differences compared to the first game, Ring: The Legend of the Nibelungen. Those include: a 3rd-person perspective (instead of 1st-person), keyboard controls (versus point-and-click), action oriented puzzles/situations, and changes in the way inventory objects are handled.' FROM games WHERE igdb_id = 73656 ON CONFLICT (game_id, language_code) DO NOTHING;
