INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The King of Fighters 2002', 'The game brings back the team play composed by three characters each that was a tradition in previous games. The game has also several important changes in the gameplay, like the "Free Cancel System" or "Max Mode System", the "Quick Emergency Evasion" and "Quick MAX Mode Activation", aside from the countless changes in each character''s special moves and their properties.' FROM games WHERE igdb_id = 5884 ON CONFLICT (game_id, language_code) DO NOTHING;
