INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Formula Suzuki Hayabusa Time Attack', 'Formula Suzuki Hayabusa Time Attack is a Playstation 2 racing advergame from Suzuki. It''s made to advertise the Formula Suzuki Hayabusa events. The best laps are to be submitted to a leaderboard in the Suzuki website (in 2002) that is currently down.' FROM games WHERE igdb_id = 349660 ON CONFLICT (game_id, language_code) DO NOTHING;
