INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dynasty-warriors-3-xtreme-legends', 45014, '2002-08-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1ouj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scia9i.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dynasty Warriors 3: Xtreme Legends', 'Dynasty Warriors 3: Xtreme Legends is a stand-alone expansion to Dynasty Warriors 3. In both games, you take control of a military general in ancient China, each with their own unique abilities and weapons. The gameplay is simple: you destroy hoards of differently ranked enemies on an open battlefield. Your objective in most missions is to defeat one or more enemy generals. Each character you choose has a different storyline (this story mode is referred to as "Musou Mode"), with seven battles progressing the story along. Battles get harder as you move along in the story. There is also a free mode, which allows you to play any level that you have unlocked with any general that you have unlocked (you start the game with three generals from three different dynasties). The difference between Xtreme Legends and the original Dynasty Warriors 3 is that in Xtreme Legends, the Musou Mode only features seven unaligned generals that you couldn''t play as outside of Free Mode. There are also challenge modes in Xtreme Legends not featured in the original. And there is a more advanced bodyguard system allowing you to name them, customize their advancement, and choose from more weapons you unlock as you play through the game.' FROM games WHERE igdb_id = 45014 ON CONFLICT (game_id, language_code) DO NOTHING;
