INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'La Pucelle Tactics', 'Prier and her brother Culotte are novices with the demon-hunting organization, La Pucelle. They''ve just passed their final exams and are ready to do real work fighting demons and zombies, but quickly find themselves embroiled in a series of plots orchestrated by a rival church with dark intentions. The gameplay is played on a tactical map, as teams up to six characters work to clear boards of enemies and dark energy. The unique "purify" command allows players to recruit monsters to their team and execute complex "miracle" energy attacks. The game was ported to the PlayStation Portable in Japan on November 26, 2009 as La Pucelle Ragnarok.' FROM games WHERE igdb_id = 6760 ON CONFLICT (game_id, language_code) DO NOTHING;
