INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'FIFA Soccer 2003', 'Master the fundamentals of soccer in FIFA Soccer 2003. With more ball control and player moves, this year''s FIFA Soccer puts the The Total Club Championship within your grasp. Unleash the skills of the world''s greatest players through new player animations and signature skill moves. Experience pressure-cooker atmospheres as you take on Europe''s elite teams in their own stadiums featuring actual team chants and songs. EA Sports Freestyle Control lets you produce a feint, one-touch pass, or skill move to leave your opponents standing.' FROM games WHERE igdb_id = 43335 ON CONFLICT (game_id, language_code) DO NOTHING;
