INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chou Kousoku Mahjong Plus', 'Choukousoku Mahjong Plus is a Mahjong game, published by Success, which was released in Japan in 2002. The game features a fast and strong Mahjong engine, over 40 sets of rules to choose from, record keeping ability, and a 2D or 3D perspective.' FROM games WHERE igdb_id = 319621 ON CONFLICT (game_id, language_code) DO NOTHING;
