INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Judie no Atelier: Gramnad no Renkinjutsushi', 'The forth game in the Atelier franchise and the first of the two Gramnad games. Both of the Gramnad games were re-released on the PlayStation Portable with additional content. The re-release is called "Atelier Judie ~The Alchemist of Gramnad~ Imprisoned Guardian" on the PSP. The game has never been released outside of Japan.' FROM games WHERE igdb_id = 26514 ON CONFLICT (game_id, language_code) DO NOTHING;
