INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'GeneRally', 'GeneRally is a simple, moddable, top-down arcade racing game for 1-6 players - available for free. The game was originally developed by Hannu and Jukka Räbinä. The game is heavily inspired by older arcade racing games, particularly Slicks ''N'' Slide. PC Gamer described it as "A minimalist Micro Machines". The game has an included Track Editor, which allows users to easily make their own tracks to race on.' FROM games WHERE igdb_id = 19280 ON CONFLICT (game_id, language_code) DO NOTHING;
