INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Onimusha 2: Samurai''s Destiny', 'Onimusha 2 is the second installment in the Onimusha series of video games released in May of 2002. The game retains the action elements from its predecessor such as the use of multiple special weapons that can be upgraded by defeating enemies. Apart from the main character, the game features four playable sub-characters, each of whom shares a part in the story. The player''s actions determine which characters will decide to help Jubei in his quest. These characters were added by the Capcom staff to give a bigger depth to the game and expand the game''s feeling of adventure.' FROM games WHERE igdb_id = 11757 ON CONFLICT (game_id, language_code) DO NOTHING;
