INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Antz Extreme Racing', '0.5 MPH is extremely fast-when your vehicle is only big enough to carry an ant! Jockey for first place with your favorite character from the hit motion picture Antz, using vehicles that aren''t your typical garden variety. Surf using a leaf, race on a fuse with wheels, even hop on a wasp for the antenna-raising thrill ride of your life! You may feel tiny, but practice will make you a giant among racers!' FROM games WHERE igdb_id = 5727 ON CONFLICT (game_id, language_code) DO NOTHING;
