INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Zelda: A Link to the Past', 'The Game Boy Advance port of A Link to the Past has some small design differences with the original version, like Link''s voice and an additional quest and dungeon unlocked after the completion of the main content. The new dungeon is only available after finishing Four Swords.' FROM games WHERE igdb_id = 229416 ON CONFLICT (game_id, language_code) DO NOTHING;
