INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hot-wheels-velocity-x', 2653, '2002-10-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2qdc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/kduo7o7olltbsqgsadxw.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hot Wheels Velocity X', 'When a criminal gang of street-racing villains overtakes futuristic Monument City, you must put their driving skills and mean street machines to the ultimate test. Hot Wheels: Velocity X is a game based on Mattel''s Hot Wheels line of miniature racing vehicles. In the game you have to drive one of over 30 Hot Wheels cars in race on the 3D curvilinear tracks, which include banded loops or crazy stunt launchers. During the race the weapon attacks and power-ups are available. The racing is mission-based with more than 37 missions across six levels to complete.' FROM games WHERE igdb_id = 2653 ON CONFLICT (game_id, language_code) DO NOTHING;
