INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('aggressive-inline', 3783, '2002-05-28', 90, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3g90.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/dm2q9p1qjnf3sfzp6tha.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aggressive Inline', 'Combine the many tricks and styles of the extreme sport, inline skating, with a Tony Hawk style system, complete with objectives and huge arenas, and you have Aggressive Inline. Progress through the career mode, where you must complete objectives (such as grind a certain object(s) to jump over large gaps and gain points) to open up further arenas, which there are 7 in all, and once your bored with them, you can make your own in the park editor. The game doesn''t use a hard time limit but the so-called "juice meter": it fills up when performing stunts and if it gets empty, the level ends. During the game you level up your character in seven stats, e.g. speed and grinds. The game uses a "learning by doing" approach to this, meaning that the stat improves if you perform the associated actions often enough. There are also five hidden keys in each level which open up new areas within the level.' FROM games WHERE igdb_id = 3783 ON CONFLICT (game_id, language_code) DO NOTHING;
