INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hard Truck: 18 Wheels of Steel', 'Be your own boss behind the wheel of your big rig. Bid on jobs, then hit the road to deliver faster than the competition. Road hazards, low fuel and even the police can affect the timeliness and condition of your deliveries - and impact your bottom line. It''s all in a day''s work when you''re driving the big rigs.' FROM games WHERE igdb_id = 50455 ON CONFLICT (game_id, language_code) DO NOTHING;
