INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Taz: Wanted', 'Taz: Wanted is an action-adventure video game featuring the Tasmanian Devil, from the Looney Tunes. Blast your way through 15 different levels, destroying "Wanted" posters to get your revenge against Yosemite Sam. The game was nominated for 2002 BAFTA award in category ''Best Children''s Entertainment''.' FROM games WHERE igdb_id = 4194 ON CONFLICT (game_id, language_code) DO NOTHING;
