INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('need-for-speed-hot-pursuit-2', 95, '2002-09-30', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2098.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/lkyquu5jl8dohcwocckw.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Need for Speed: Hot Pursuit 2', 'The Need for Speed series returns, this time reverting back to the ''chase'' arcade experience instead of a racing simulation. Top speed racing is the name of the game, where you must outchase not just the opposing drivers, but the cops. Choose from a selection of today''s (and yesterday''s) top sports cars, including the Ferrari F50, Porsche 911 and a range from the likes of Ford, Corvette, BMW, Lotus, Mercedes, Aston Martin, the McLaren F1 and a lot more. The competitive race mode allows you to take on other drivers and beat them to the line. A selection of tracks allows you to not only dodge incoming traffic, but perform deadly jumps and stunts to receive points. These points, combined with the points recieved from your finishing position, can unlock new cars and tracks. The Hot Pursuit mode combines all the major elements of the competitive mode with the chance to out run the cops. They will throw everything at you to try and stop you, including running you off the road, setting up road blocks and unleashing an attack helicopter equiped with missiles. Three busts by the cops ends the race.' FROM games WHERE igdb_id = 95 ON CONFLICT (game_id, language_code) DO NOTHING;
