INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Time Crisis 3', 'The third installment in Namco''s light gun shooting franchise, Time Crisis 3 offers exciting, fast-paced shooting action by the world renowned VSSE agents as they fight to save an innocent nation from total annihilation. Choose from four weapons--machine gun, handgun, shotgun, and grenade-- to blast your way past enemies. Practice your sharpshooting skills in Sniper Combat and multiple gameplay modes. The game also includes multiple gameplay modes, a new playable character, and the original Time Crisis. It''s time to warm up that trigger finger and step into the action.' FROM games WHERE igdb_id = 13894 ON CONFLICT (game_id, language_code) DO NOTHING;
