INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('disneys-pooh-and-tiggers-hunny-safari', 50008, '2002-01-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1w9d.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc7in0.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Pooh and Tigger''s Hunny Safari', 'A.A. Milne''s beloved characters come to interactive life in this wonderful expedition through the Hundred Acre Wood. In order to ensure their party will be, Pooh and Tigger are going to need some honey (known in Milne''s world as "hunny"). In fact, the duo will need to find dozens of pots full of the stuff, and that will mean searching the entire forest. Much to Pooh and Tigger''s collective dismay, the area is populated by dozens of insects, angry animals, and environmental dangers. In addition to searching for the hunny, you''ll have to help your pals find such popular characters as Rabbit, Piglet, and Owl, as well as unlocking dozens of hidden areas and special power-ups. Three mini-games Veggy Match, River Run, and Fence Off can also be uncovered, and you can save all of your progress and resume play with a password. The game spans 18 levels and five diverse environments including The Spring Glade, The Nighttime Forest, Autumn Heights, Creepy Caves, and Winter Wood.' FROM games WHERE igdb_id = 50008 ON CONFLICT (game_id, language_code) DO NOTHING;
