INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hearts of Iron', 'Hearts of Iron is the first ever World War II PC game of true Grand Strategic scope. The game map spans the entire world and allows players to take part in any front they choose. You can play any nation in the world, but the game focuses on the epic struggle between the great alliances of the world orders - Fascism, Communism and Democracy.' FROM games WHERE igdb_id = 22227 ON CONFLICT (game_id, language_code) DO NOTHING;
