INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NFL Blitz 20-02', 'The NFL Blitz 20-02 incarnation promises deeper gameplay, more animations, better AI, more mini-games, and even harder hits. Still focusing on its roots of hard-hitting football action with no rules whatsoever, the game hopes to hit the consoles as hard as its players hit each other.' FROM games WHERE igdb_id = 23443 ON CONFLICT (game_id, language_code) DO NOTHING;
