INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Revenge of Shinobi', 'Set in the mythical world of ancient Japan, players take on the role of ninja warrior Shinobi. To free the world from the curse of Goaku, Shinobi must recover 5 elemental swords and defeat the Shoguns who wield them. It will take stealth, strength, and the mastery of the mystic arts for Shinobi to battle his way through the 5 lands. While the game shares a name with the third game in the Shinobi series, it''s a stand-alone spin-off title not based on the previous game.' FROM games WHERE igdb_id = 10222 ON CONFLICT (game_id, language_code) DO NOTHING;
