INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('klonoa-2-dream-champ-tournament', 6493, '2002-08-06', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3zgr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/x7xhdmxynuxq4ktqzkld.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Klonoa 2: Dream Champ Tournament', 'Floppy-eared hero Klonoa returns in another fast-paced, colorful side-scrolling adventure for the Game Boy Advance. In his latest challenge, Klonoa must race against time and other dream travelers in the Dream Champ Tournament to collect stars, sun and moon stones to become the ultimate Dream Champion. Combining platform, puzzle and adventure elements, Klonoa 2: Dream Champ Tournament is just the adventure fans of the series have been anticipating. Explore the intricate and puzzle-packed worlds where you’ll meet a wide variety of interesting creatures! Solve Fiendishly-Designed Puzzles - Use Boxes, Bomb Boxes, Switches, Pressure Switches, Goomis, Springs and Scales in your quest for glory. Hoverboard Races - Each world contains a fast-paced thrill ride of gem collecting fun! Master your Skills to Win - Klonoa must prove his skills against other dream travelers in the Dream Champ Tournament.' FROM games WHERE igdb_id = 6493 ON CONFLICT (game_id, language_code) DO NOTHING;
