INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sigame--1', 285584, '2002-12-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7q68.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scqfw5.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SIGame', 'SIGame is an intellectual quiz in which everyone can test their knowledge and reaction speed and fight against opponents. Game rules are very simple: all questions in the game are divided into themes, and each question in the theme has its own price. Each player has a personal score, which at the beginning of the game is 0. A question is presented, after which a frame appears on the screen indicating that you can press the button and answer. If the player knows the answer, he/she can press the red button. The player who presses the button earlier than others (and will not have a false start), gives an answer. If the answer is correct, the question price is added to the player''s score; otherwise - the price is substracted from the score. In the latter case, other players can try their luck and press the button to answer. The game can also have a final round in which each of the players makes a bet. A question is asked, time is given for thinking, and each of the players submits their answer to the host. After that, the correct answer is announced, and each of the players receives or loses money according to their bet. Game winner is the player with the highest score after the last question.' FROM games WHERE igdb_id = 285584 ON CONFLICT (game_id, language_code) DO NOTHING;
