INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gran-turismo-concept-2002-tokyo-geneva', 22061, '2002-07-17', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co20bd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8jp1.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gran Turismo Concept: 2002 Tokyo-Geneva', 'Gran Turismo Concept is a racing video game of the Gran Turismo series for PlayStation 2 which is developed by Polyphony Digital. It is essentially a short version of Gran Turismo 3: A-Spec, but with concept cars that ended up in Gran Turismo 4. It was released in 2002 in Japan, Southeast Asia, Korea, and Europe. For undisclosed reasons, the game was not released in the North American market, although a stripped-down version of it was released in form of Gran Turismo: Nissan 350Z Edition. A last version of Gran Turismo Concept, 2002 Tokyo-Geneva, was released in Europe on July 17th, 2002. It featured all the cars from the 2002 Tokyo-Seoul version plus new models unveiled at the Geneva Motor Show. A Chinese/English NTSC version was released in the Southeast Asia on July 25th, 2002, it adds 30 cars to the 2001 Tokyo version released earlier in this area. As of April 2008, Gran Turismo Concept 2002 Tokyo-Geneva has shipped 1 million copies in Europe and 30,000 in Southeast Asia. This short version title followed the release of the full-length version Gran Turismo 3: A-Spec in 2001 and was eventually followed by Gran Turismo 4.' FROM games WHERE igdb_id = 22061 ON CONFLICT (game_id, language_code) DO NOTHING;
