INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Thing', 'While investigating the enigmatic deaths of American scientists in the Antarctic, a military rescue team encounters a strange shape-shifting alien life-form that assumes the appearance of the people it kills. As the team leader, you must forget everything you ever learned about obliterating aliens simply with a barrage of violent ammunition--this monster is difficult to see, hard to kill, and seemingly impossible to evade. In the midst of this lurking terror, you must convince your squad to cooperate and complete tasks essential to both the success of the mission and your own survival.' FROM games WHERE igdb_id = 6199 ON CONFLICT (game_id, language_code) DO NOTHING;
