INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The House of the Dead III', 'The House of the Dead III is a 2002 light gun arcade game with a horror zombie-survival theme, and the third installment to the House of the Dead series of video games, developed by Wow Entertainment and Sega. It was later ported to the Xbox in 2003, Microsoft Windows in 2005, the Wii in 2008 in a compilation with The House of the Dead 2, and PlayStation 3 in 2012 with PlayStation Move support. The game continues the story of the previous games and introduces new gameplay concepts such as story branching. The game''s protagonist is Lisa Rogan, daughter of Thomas Rogan, the first game''s main character, and players control Lisa, G, or Daniel Curien.' FROM games WHERE igdb_id = 5863 ON CONFLICT (game_id, language_code) DO NOTHING;
