INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-legend-of-zelda-ocarina-of-time-master-quest', 45142, '2002-11-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5zdv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sckjrf.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Zelda: Ocarina of Time - Master Quest', 'The Legend of Zelda: Ocarina of Time - Master Quest is a reworked version of the original Ocarina of Time for the Nintendo 64. Master Quest contains largely the same content as the original game but with more redesigned and difficult dungeons. Master Quest was available on a special bonus disc that also contained the original Ocarina of Time, it was given out in limited quantities with preorders of The Wind Waker. It was previously developed to be released as an expansion to the original game via the Nintendo 64DD, but that version was cancelled due to the lackluster sales of the hardware.' FROM games WHERE igdb_id = 45142 ON CONFLICT (game_id, language_code) DO NOTHING;
