INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monopoly', 'Monopoly brings the popular board game to life with animated tokens, bright graphics, and your choice of 10 different major city game boards, plus the classic Monopoly game board. As with the original version, you must buy and maintain as many properties as you can without going bankrupt. Now, you can use your strategies against five other people on one system or over the Internet. Also included in the package is a special Monopoly game token.' FROM games WHERE igdb_id = 71296 ON CONFLICT (game_id, language_code) DO NOTHING;
