INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NightCaster: Defeat the Darkness', 'NightCaster is a third-person, single-player, action-adventure game for the Xbox, developed by VR1 Entertainment and published by Microsoft. Players take the role of Arran, a novice wizard whose magical power grows as he ages throughout his quest to collect spells and rid the world of eternal night. NightCaster was released on December 26, 2001 and its ESRB rating is Teen. In December 2002, the sequel, NightCaster II: Equinox, was released, with two-player compatibility. The game received generally middling reviews with a Metacritic average of 61' FROM games WHERE igdb_id = 47323 ON CONFLICT (game_id, language_code) DO NOTHING;
