INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Post Mortem', 'After returning to the quiet streets of Paris to pursue a life of painting, Gus Macpherson could not escape his true art… The former New York detective finds himself walking the beat once again, when hired by a sensuous woman to investigate the gruesome beheadings of her sister and brother-in-law. In the dark and mysterious streets of Paris and plagued by his clairvoyant sixth sense, Gus will uncover a conspiracy written in blood, with rituals and artifacts as old as time itself.' FROM games WHERE igdb_id = 14359 ON CONFLICT (game_id, language_code) DO NOTHING;
