INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Patrician III', 'Patrician III is a real-time trading simulation featuring elements of construction and the historical background of maritime trade in Northern Europe during the 1300''s. As a resident of a medieval town, your goal is to rise from the status of a simple, insignificant trader to that of a Patrician and perhaps even become the head of the Hanseatic League. You can raise your standing through town improvement and diplomacy or fill your coffers through piracy and smuggling.' FROM games WHERE igdb_id = 287 ON CONFLICT (game_id, language_code) DO NOTHING;
