INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Hunchback of Notre Dame', 'The ugliest man in Paris, bell-ringer Quasimodo is mocked or ignored by everyone in the city. Then, one day, Quasimodo falls in love with the dancer, Esmeralda, and his life changes forever. As well as a great 50 minutes cartoon video, Hunchback of Notredame features an easy-to-use virtual colouring book and a challenging puzzle game. Can the hunchback find love?' FROM games WHERE igdb_id = 54301 ON CONFLICT (game_id, language_code) DO NOTHING;
