INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('flash-flash-revolution', 62802, '2002-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2q61.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sciiqd.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flash Flash Revolution', 'Flash Flash Revolution (or FFR) is a music-based rhythm game that runs through an Adobe Air desktop application, making it a fully-fledged online music title that requires no fees to play. Players can choose from well over 2,000 songs from a number of genres, produced by popular signed and independent artists. Each game level has a pattern of arrows which correlate to the current song being played. The pattern of arrows scrolls from the bottom of the play field (by default) and players must hit the arrows when they meet the stationary receptors located at the top of the play field.' FROM games WHERE igdb_id = 62802 ON CONFLICT (game_id, language_code) DO NOTHING;
