INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cabela''s Ultimate Deer Hunt 2', 'Cabela''s Ultimate Deer Hunt 2 is a realistic hunting simulation with 6 large maps and a variety of deer types. Hunt in Texas, Washington, Alaska, Missouri, Idaho and Michigan. Choose quick hunt for instant action, or mission-based play to face a series of 26 specific challenges. Customize your hunting experience with a wide selection of gear, and set off on your virtual hunt, with full 3D terrain, trees and grass.' FROM games WHERE igdb_id = 51334 ON CONFLICT (game_id, language_code) DO NOTHING;
