INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Britney''s Dance Beat', 'Singer Britney Spears is looking for backup dancers for her next world tour, and she wants you to audition. Show Britney your hottest moves by keeping to the beat of her most popular songs, including "Oops! I Did It Again" and "I''m a Slave 4 U." Then, answer trivia questions to prove your Britney knowledge. The game rewards true fans with exclusive video footage, access to more songs, and the chance to dance alongside Britney.' FROM games WHERE igdb_id = 6338 ON CONFLICT (game_id, language_code) DO NOTHING;
