INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mafia', 'Mafia is a 3D action crime epic set in the seedy underworld of the 1930''s. Rise from the lowly but well-dressed Footsoldier, to an envied and feared Made Man in an era of mob hits, car chases, and bootlegging. Earn a reputation as a tough enforcer, daring getaway driver, and deadly hitman in your quest for respect and power within the Salieri Family.' FROM games WHERE igdb_id = 39 ON CONFLICT (game_id, language_code) DO NOTHING;
