INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Project Nomads', 'Project Nomads is set on the fictional planet Aeres, a fantastic world of gigantic floating islands, which are the remnants of the planet from before it exploded. After Aeres broke apart, the few surviving inhabitants settled on the drifting fragments of the planet. You are a nomad, a restless soul forever in pursuit of adventure. You wander across the planet on your island, discovering mysterious artifacts and exploring the ruins of the long dead race of Master Builders. The only place to fall to is the Sea of Flames, the very bottom level of this new world.' FROM games WHERE igdb_id = 50245 ON CONFLICT (game_id, language_code) DO NOTHING;
