INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bravo Music: Chou Meikyokuban', 'One of three Japan-exclusive sequels to Bravo Music/Mad Maestro! Bravo Music - Chou Meikyokuban: Your goal is to play four beautiful songs for the Martians who have already left Mars and are on their way to Earth! They will arrive in one week''s time, so you have seven days to play four beautiful songs - even if you screw up the song, it counts as a day, so do your best! In Child Mode you can choose from six planets, each leading to a different song.' FROM games WHERE igdb_id = 269384 ON CONFLICT (game_id, language_code) DO NOTHING;
