INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pacmania-ii', 245391, '2002-03-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6dpy.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PacMania II', 'PacMania II is the fourth game in the Alawar PacMania series based on the original Pac-Man. Like in Pac-Man, all the dots from a board need to be eaten in order to pass to the next board. If the characters bumps into a monster, he loses a life. There are special pills in every stage allowing the character to eat the monsters for a short period of time. The game contains three game modes: Classic: this is the original style of Pac-Man*, the player is the yellow dot muncher, and the enemies are the four ghosts. - Advanced: in this type the player''s character is a pair of big lips and the enemies are skeletons. - CarMania: in this type the player is bulldozer and the enemies are little cars. Objects turn into fuel tanks, screwdrivers and hearts. This third mode was added in an updated version. In every game type there are also bonuses. Most of them offer points and hearts provide extra lives. For every five completed levels a password is provided to continue from there.' FROM games WHERE igdb_id = 245391 ON CONFLICT (game_id, language_code) DO NOTHING;
