INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flight Academy', 'Flight sim, built on the advanced GIN-YOKU system. Instead of serving up airborne battle action, Flight Academy lets players experience what it''s like to be a passenger jet pilot. Would-be pilots work their way up from a single-prop A36 plane all the way to a full-sized airliner. The game lets players explore take off and land from multiple Japanese airports and explore the airspace over several islands in the Pacific.' FROM games WHERE igdb_id = 62999 ON CONFLICT (game_id, language_code) DO NOTHING;
