INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stronghold Deluxe', 'Firefly Studios'' Stronghold Deluxe is a re-release of Stronghold that comes pre-patched to version 1.2. It also includes additional maps based on sieges, economic missions and invasions. Historical maps included enable the player to reconstruct sieges of famous strongholds such as Camelot, Mordred''s fortress, Tintagel, Edinburgh, Koblenz Stolzenfels and the Tower of London.' FROM games WHERE igdb_id = 98961 ON CONFLICT (game_id, language_code) DO NOTHING;
