INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Moto GP: Ultimate racing technology', 'MotoGP puts you behind the handlebars of some of the fastest machines on two wheels. Take control of any of the bikes and riders from the world of Grand Prix Motorcycle racing, and race across 10 real-world tracks in a variety of game modes. In Grand Prix and Training modes, you can develop your own rider''s attributes and then race to unlock tracks, riders, cheats, and bikes. Show off your speed and style in single-player tournaments or multiplayer races.' FROM games WHERE igdb_id = 8268 ON CONFLICT (game_id, language_code) DO NOTHING;
