INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aikagi: Hidamari to Kanojo no Heyagi', 'A visual novel from F&C FC02. Takashi Murase lived an average live along his father but one day, he suddenly died in a car accident. Unable to live by himself, Takashi''s homeroom teacher will start living in his house to take care of him - and her sister''s joining this new family too! What will be of the three of them..?' FROM games WHERE igdb_id = 58098 ON CONFLICT (game_id, language_code) DO NOTHING;
