INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SonKnuck Adventure', 'SonKnuck was peacefully relaxing at home when he received a letter asking him to go on Party Land and bring his "SK-emeralds". At first he thought the author was his friend Amykal but he then realized that she has no way to mail him. So, he decided to go on Party Land anyway but he''s been careful and decided to hide his emeralds everywhere on Party Land. But he didn''t know his mortal ennemy was waiting for him...' FROM games WHERE igdb_id = 330068 ON CONFLICT (game_id, language_code) DO NOTHING;
