INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zoids VS', 'The first incarnation of the Zoid Vs series, released in Japan in 2002. The game was noted for its ragdoll-like movement when Zoids were hit back or killed. In this game, the Battle Mode is limited to only one set, meaning that no matter what character the player chooses, the battles are all the same. That said, the Battle Mode features characters and Zoids from Chaotic Century, New Century, and the Zoids VS story lines.' FROM games WHERE igdb_id = 50586 ON CONFLICT (game_id, language_code) DO NOTHING;
