INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wonderland', 'Wonderland is a top-down box pusher puzzle game. To complete one of the 60 levels, you have to collect all rainbow coins to unlock the exit and then reach the exit with all characters in the level (1 or 2). Puzzle elements include wooden crates, conveyor belts, teleporter, walking bombs and more.' FROM games WHERE igdb_id = 95460 ON CONFLICT (game_id, language_code) DO NOTHING;
