INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Trek Voyager: The Arcade Game', 'After a hearty "Welcome aboard!" from Captain Janeway, you start your adventure on Voyager, which is quickly overrun with Borg. After 6 shots, your phaser must be "recalibrated" by firing off-screen. The game includes occasional opportunities for weapons upgrades, life upgrades and bomb detonation. The game expands to various areas of Voyager and to the Borg ship, and introduces additional aliens along the way. The game also includes a space scenario which simulates a shuttle flight where you fire at various Borg ships.' FROM games WHERE igdb_id = 51620 ON CONFLICT (game_id, language_code) DO NOTHING;
