INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hot Wheels: Bash Arena', 'Hot Wheels Bash Arena for PC challenges players to dodge and crash into opponents with performance varied Hot Wheels cars in a last car standing, interactive demolition derby-style competition. The game features 20 authentic Hot Wheels cars to unlock and control in six dynamic multi-level arenas full of hazards. Vehicles will gather real-time damage while in competition, and can use more than 20 offensive and defensive power-ups to restore their condition. As players advance through the Bash Arena championship, they work their way toward the ultimate goal of induction into the Hot Wheels Bash Arena Hall of Fame.' FROM games WHERE igdb_id = 70992 ON CONFLICT (game_id, language_code) DO NOTHING;
