INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Curse of Atlantis: Thorgal''s Quest', 'Assuming the role of Thorgal Aegirsson, a Viking warrior and son of Storms and the Sea, you travel through various locations filled with characters from Norse mythology. Upon meeting an elderly man, he unveils a prophetic mirror showing Thorgal''s son dying at his own hands. Determined to change this fate, Thorgal embarks on a quest to protect both family and community from impending divine retribution.' FROM games WHERE igdb_id = 23696 ON CONFLICT (game_id, language_code) DO NOTHING;
