INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Soul Falchion', 'Soul Falchion is a weapon-based fighting game using Takara''s engine. It has 20 characters, most (if not all) of which are based on characters from SNK''s Last Blade and Samurai Shodown series, renamed (some with names taken from Mortal Kombat), slightly modified and recolored. The sprites are smaller versions of the sprites used in the Neo Geo Pocket Color games.' FROM games WHERE igdb_id = 271791 ON CONFLICT (game_id, language_code) DO NOTHING;
