INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 2000 Series Ultimate Vol.19: Akagi - Yami ni Furitatta Tensai', 'Agaki Yami ni Oritatta Tensai: A character-driven mahjong game based on comics 1 through 6 in the Akagi series. Players become Akagi as he takes on opponent after opponent in strategic mahjong battles. The game features also other game modes like free mahjong mode, but the main mode is the story mode in which the player will advance through the story that is divided into stages winning mahjong matches.' FROM games WHERE igdb_id = 56958 ON CONFLICT (game_id, language_code) DO NOTHING;
