INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blip & Blop: Balls of Steel', 'Pac-Man is a ball with a mouth; Blip and Blop are balls with arms -- conventional arms of several varieties, in addition to more exotic heavy weaponry such as lasers and flamethrowers. Chekhov''s law dictates that the gun in the first act must go off in the third, but these hardened spheres haven''t got the patience for that, wading directly into a non-stop carnival of carnage, a shooting frenzy only occasionally interrupted with cut-scene dialogue and nods to what might otherwise be described as the run''n''jump platformer genre -- had they legs to run and jump with.' FROM games WHERE igdb_id = 50127 ON CONFLICT (game_id, language_code) DO NOTHING;
