INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kids Station: LEGO no Sekai', 'Kids Station: Lego no Sekai is a Japan-exclusive educational game that uses an animal world made of Lego pieces to teach young kids about numbers, letters, shapes and other intellectual training mini games. The game uses different kind of animals like: panda, elephant, monkeys, pony, etc to explain and do each mini game. This is one of the few Kids Station games that doesn''t come with the Kids Station controller in any release.' FROM games WHERE igdb_id = 313552 ON CONFLICT (game_id, language_code) DO NOTHING;
