INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crossfire II', 'Crossfire II is an Retro / Arcade / Top-Down Shooter, originally released in 2002 for the AMIGA. The main part of the game is a classic, fast paced, single player story campaign. Fly different space ships and fight, to save the universe as you know it. Also you get a survival and a local PvP mode.' FROM games WHERE igdb_id = 170284 ON CONFLICT (game_id, language_code) DO NOTHING;
