INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tzar: Gold Edition', 'This release covers all previous Tzar games and scenarios, adding a new campaign as well as a map creator. This last feature allows for the creation of adventures with special events, conversations and rules and the ban of technologies and units at the player''s pleasure. These maps are 100% compatible with the game and they can be accessed directly through it. The aforementioned new campaign is focused on Gengis Khan''s empire, showcasing it in a total of two scenarios.' FROM games WHERE igdb_id = 176020 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 176020 AND ge.slug = 'real-time-strategy-rts' ON CONFLICT DO NOTHING;
