INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kong: The Animated Series', 'Our modern world and an ancient land have come together on Kong Island, a secret world of prehistoric beasts which protects the 13 sacred stones - the key to ultimate power! Join Kong, Jason and his friends in an amazing platform adventure, battling prehistoric creatures, to rescue the stones from the forces of evil and save the planet.' FROM games WHERE igdb_id = 49333 ON CONFLICT (game_id, language_code) DO NOTHING;
