INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Big Brother Brasil', 'Big Brother Brasil is a simulation game based on the reality show by the same name, developed by Continuum and published by Brasoft in collaboration with Rede Globo. Choose your character according to its physical and psychological characteristics, relate to the other participants, and form plots - but be careful! The audience is following everything and, if you go to the chopping block, you may be evicted.' FROM games WHERE igdb_id = 140880 ON CONFLICT (game_id, language_code) DO NOTHING;
