INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hugo: Frog Fighter', 'One beautiful summer''s evening, the frogs suddenly stop croaking. Don Croco''s soldiers are busy catching all the frongs for a barbecue. And so Hugo sets off on a journey through the Swamp, Jungle, Crystal Grotto and the Factory to save the frogs.' FROM games WHERE igdb_id = 25666 ON CONFLICT (game_id, language_code) DO NOTHING;
