INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Robot Rubble', 'A robot is shooting at you - lob a grenade to destroy it. Boom! But once it''s gone, a tougher robot takes its place!  Steve Montero developed this game at Activision after programming the robot-themed Night Stalker at Mattel Electronics. The game was completed in late 1983, just as Activision decided to give up on releasing new Intellivision titles. It was finally released in 2001 on the Intellivision Rocks CD.' FROM games WHERE igdb_id = 41479 ON CONFLICT (game_id, language_code) DO NOTHING;
