INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ghost Vibration', 'In this first person shooter on rails you are George, a ghost hunter, accompanied by his childhood friend and scientist Alicia. You have to exterminate the ghosts that inhabit an old mansion using a special weapon called Spirit Gun. After capturing the various spirits you can read their memories and use this information to solve the mysteries of this ancient mansion.' FROM games WHERE igdb_id = 43420 ON CONFLICT (game_id, language_code) DO NOTHING;
