INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Trigon', 'Star Trigon is a 2002 puzzle arcade game published in Japan by Namco. Ports for iPod, iOS devices and Windows were also released. In the game, the player controls one of three characters - Wataru Hoshi, Chuta Bigbang and Susumu Hori - the objective being to rescue creatures known as "Uchijins" by hopping from planet to planet to draw triangles and capture them. The player will automatically circle the planet they are on, requiring timed jumps to avoid falling off the playfield.' FROM games WHERE igdb_id = 54399 ON CONFLICT (game_id, language_code) DO NOTHING;
