INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harry Potter: Skurge Challenge', 'Skurge Challenge was a small 2D mini-game that was coming with promotional CDs Harry Potter and the Chamber of Secrets video game. That CD was also including screensavers, wallpapers and demo versions of first two Harry Potter games. After completing Skurge Challenge the players could get access to a secret level within Harry Potter and the Chamber of Secrets video game. The secret level can be also be accessed by using the debug mode' FROM games WHERE igdb_id = 305737 ON CONFLICT (game_id, language_code) DO NOTHING;
