INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cleopatra Fortune Plus', 'Cleopatra Fortune Plus is an Egyptian themed falling block puzzle game following Cleopatra Fortune. Expanding on the original, blocks can be rotated counter-clockwise, breaking colored gems builds up items with powerful effects when cleared, and a rival that can drop larger blocks appears. In addition, a story mode is present unlike the original.' FROM games WHERE igdb_id = 254954 ON CONFLICT (game_id, language_code) DO NOTHING;
