INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NCAA College Football 2K3', 'It''s time to hit the turf and get ready for another round of NCAA football action. NCAA College Football 2k3 is here and it''s full of updated rosters, teams and stadiums to fulfill all of your college football needs. Play as your favourite up-and-comers with a friend to see who''s the best. NCAA College Football 2k3 is here for the Microsoft Xbox and it''s go time. Hut, hut!' FROM games WHERE igdb_id = 4039 ON CONFLICT (game_id, language_code) DO NOTHING;
