INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jimmy Neutron vs. Jimmy Negatron', 'Jimmy Neutron Boy Genius has gotten himself in a completely new world of trouble, or should we say "new dimension of trouble?" In The Adventures of Jimmy Neutron, Boy Genius: Jimmy Neutron Vs Jimmy Negatron, Jimmy accidentally warps himself into a parallel dimension, switching places with his evil alter ego -- Jimmy Negatron! With Jimmy Negatron running loose in Retroville, Jimmy Neutron will need all of his inventions and smarts to figure a way back home, save his friends, and restore his town back to normal!' FROM games WHERE igdb_id = 6478 ON CONFLICT (game_id, language_code) DO NOTHING;
