INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sven-Göran Eriksson''s World Challenge', 'Sven-Göran Eriksson''s World Challenge is a soccer game. It features 204 national teams from all over the world. There are six playing modes: Exhibition match, training, league, play-offs, World Cup qualification or World Cup championship. It uses the same handling as the Kick Off series, which means the ball doesn''t stick to the players'' feet.' FROM games WHERE igdb_id = 66508 ON CONFLICT (game_id, language_code) DO NOTHING;
