INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sakura Taisen 4: Koi seyo, Otome', 'Sakura Wars 4 was promoted as the "Grand Finale" of the Sakura Taisen franchise and while the series did continue after the fourth entry, Fall in Love, Maidens was the final game to feature the franchise''s original cast. The game brought an end to the story of the series'' hero, Ogami, and all of his relationships with the characters throughout the series were brought to a finale.' FROM games WHERE igdb_id = 93261 ON CONFLICT (game_id, language_code) DO NOTHING;
