INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hamtaro: Ham-Ham Heartbreak', 'All the hamsters are bickering, and there''s little wonder why! Spat, a meddling troublemaker, is telling fibs and causing heartache everywhere. It''s up to Hamtaro and best-girl Bijou to follow Spat, stop the squabbling, and get everyone back on talking terms again.' FROM games WHERE igdb_id = 6428 ON CONFLICT (game_id, language_code) DO NOTHING;
