INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('all-star-racing', 43931, '2002-11-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/yalufprdrurlx5e1l7nw.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'All Star Racing', 'All Star Racing combines four distinct racing modes: GT Racer, Stockcar Frenzy, Classic Cars, and Supercar Challenge. Pre-race options include difficulty setting (easy, medium or hard), number of laps (3-lap sprints to 15-lap endurance races), Dualshock vibration, and sound volume adjustments. This budget title from Mud Duck Productions offers single races against five computer-controlled opponents and a choice of three cars per racing style. No multiplayer or career modes are available.  Each race style includes three courses and three types of vehicles. The classic cars (Stalwort, Belling V2, and SK MK2) race on or through mountains, hillsides, and forests. GT cars (GSX, GT2R and CRX2) run at Iona, Boulder, and Hampton speedways, while Champ Team, File Team, and SPD Team stockcars race on runway, countryside, and urban tracks. The super cars (Pina 238, Fenzo 500, and Manelli 748) compete on hills, ridges, and a forest-valley track.  All Star Racing includes GT, stockcar, super cars, and classics racing on a limited number of fictional tracks. Though released in 2002, All Star Racing''s graphics and gameplay are reminiscent of early to mid-90s racing titles.' FROM games WHERE igdb_id = 43931 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 43931 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
