INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mike Tyson Heavyweight Boxing', 'Mike Tyson Boxing proves that one of history''s oldest sports is also one of its bloodiest. The game allows boxers to deliver intense pain to their opponents with 600 brutal power punches, illegal moves, signature blows, and combos. As one of the game''s professional pugilists, or your own customized fighter, you''ll work your way through the bronze and silver ranks for a one-on-one meeting with Mike Tyson.' FROM games WHERE igdb_id = 24076 ON CONFLICT (game_id, language_code) DO NOTHING;
