INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('adventurequest', 79499, '2002-07-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1s7k.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sckatv.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'AdventureQuest', 'AdventureQuest is a fully animated RPG that you can play when you are on your lunchbreak, when the big game servers go down, or even for hours every day! You fight against hordes of monsters and enemies so that you can grow stronger and obtain ancient weapons of unimaginable power. Explore an entire world, filled with over 700 monsters, hundreds of items, magical powers to gain, and many classes to master! Become a Fighter, Wizard, Ninja, Vampire Slayer, Rogue, Knight, Mage, Paladin, Dragonslayer, and more.' FROM games WHERE igdb_id = 79499 ON CONFLICT (game_id, language_code) DO NOTHING;
