INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Price Series: Block & Switch', 'Puzzle game in which the players controls a little girl that is trapped in different mazes and have to solve the mazes using different kind of blocks: a static block and a pushing block. The gameplay is about using those blocks to insert the keys in the keyholes, when all the keys are inserted in each level the level is cleared. There are a lot of different puzzles to solve in 2d cartoon graphics.' FROM games WHERE igdb_id = 267225 ON CONFLICT (game_id, language_code) DO NOTHING;
