INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TipTop', 'It''s hip, daddy-o! Are you a fan of puzzle games and Vegas fifties-style fruit machines? Then TipTop is right up your alley!  Match and clear all the slots, use magnets (pull a column up), anvils (push a column down), Jokers, Dynamite and "Color Bombs" (get rid of various items), bombs and other special blocks to score crazy combos, but don''t break the bank!  It''s a blast!' FROM games WHERE igdb_id = 136413 ON CONFLICT (game_id, language_code) DO NOTHING;
