INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'VeggieTales: Veggie Carnival', 'Join in the grand opening of the Veggie Carnival, where kids play five hilarious carnival games with the Veggies and win loads of tickets. Aim for a high score in Dartguns in Dodge or take a wild ride in Bumper Clickers. Watch the wacky Veggie robots sing silly songs. Clown around by dressing up your favorite Veggies in hats, wigs, and funny clothes. When you''ve earned enough tickets, climb aboard the Bobbereeno for a thrilling roller coaster ride with--who else--the Veggies.' FROM games WHERE igdb_id = 124304 ON CONFLICT (game_id, language_code) DO NOTHING;
