INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vampiromania: O Game', 'Vampiromania is a game that mixes action and role-playing, where the player controls 3 characters individually - Teodor, Petru and Ecaterina - who possess different characteristics. Teodor is a strong man who fights with his hands and protects the group with his shield. Petru, the boy, uses his sling to attack the enemies and Ecaterina is a fast woman with good kicking abilities. The objective of the group is to find the terrible Vlad Tepes and to destroy him. Three types of different enemy creatures exist during the game: vampires, buzz and ghosts.' FROM games WHERE igdb_id = 163702 ON CONFLICT (game_id, language_code) DO NOTHING;
