INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kelly Club: Pet Parade', 'Hang out with Kelly, Keeya, Chelsie, and Tommy as they choose outfits and decorate floats. Groom your pets, teach them fun new tricks, and play fun arcade games in between preparations Watch the parade come to life as the crowd cheers for your posh pets Print out images of your perfect pet to share with others' FROM games WHERE igdb_id = 209843 ON CONFLICT (game_id, language_code) DO NOTHING;
