INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Historion: ... und Geschichte wird zum Abenteuer', 'The player is a time traveller with the mission to save the classical era. To do this, he has to solve history-based puzzles, fight enemies and collect four magic gems. The player collects items and stores them in the inventory for further usage. The game takes place in Greek towns, harbors and four of the seven Wonders of the World. An in-game knowledge base is included.' FROM games WHERE igdb_id = 284652 ON CONFLICT (game_id, language_code) DO NOTHING;
