INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tetris', 'Tetris for Wonderswan Color is the first Tetris Guideline compatible game in Japan. Tetris is one of the great many versions of the famous soviet block-stacking game. Pieces made up of four blocks (dubbed "tetriminoes") fall into a 10x20 square well, and must be arranged into complete lines, which then vanish and clear more space on the board. As lines are cleared, the game speed increases until either the tetriminoes reach the top of the well or the player completes the goal for the current mode.' FROM games WHERE igdb_id = 185669 ON CONFLICT (game_id, language_code) DO NOTHING;
