INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Smoke Attack', 'Smoke Attack is a top-down shooter game made for the Swiss government as part of an anti-smoking campaign. The player fights against the aggressive smoking balls with cigarettes by shooting them with an oxygen gun. The goal is to reach the next level and fight even more smoke. On each level players can find extra ammunition, secret weapons and hidden keys. The gameplay is non-violent; after being shot smoking balls are turned into oxygen.' FROM games WHERE igdb_id = 216275 ON CONFLICT (game_id, language_code) DO NOTHING;
