INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Demonworld: Dark Armies', 'Demonworld: Dark Armies is a real-time strategy game that plays similar to the Warhammer franchise. Demonworld: Dark Armies'' idea of a real-time strategy is gigantic armies of different races clashing on large battlefields in a variety of environments. If you are a fan of the Warhammer series, it would be a good idea to pick this game up.' FROM games WHERE igdb_id = 73841 ON CONFLICT (game_id, language_code) DO NOTHING;
