INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Courage the Cowardly Dog: Creep TV', 'Courage In Creep TV is an adventure game starring Courage The Cowardly Dog. Eustace and Muriel were captured by poltergeists and put inside the TV and it''s Courage''s job to rescue them again. The game uses a top-down perspective and Courage can pick up objects, combine and use them. After picking up the remote control of the TV and putting batteries into it, Courage can shoot the poltergeists in his house and keep them away from him.' FROM games WHERE igdb_id = 186279 ON CONFLICT (game_id, language_code) DO NOTHING;
