INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MotoGP Ultimate Racing Technology', 'Based on the immensely popular sport of Grand Prix Motorcycle racing, MotoGP is an ultra-realistic bike racer for the Xbox which puts you, the player, behind the handle-bars of some of the meanest, fastest, most thrilling machines on two-wheels. With a variety of innovative gameplay elements, supported by amazing graphics and revolutionary technical features, MotoGP brings the perfect mix of speed, style, bravery and technology to your Xbox console.' FROM games WHERE igdb_id = 47351 ON CONFLICT (game_id, language_code) DO NOTHING;
