INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('monster-force', 49390, '2002-09-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1j8s.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monster Force', 'Back in the days of mobs and torches monsters had a hard time fitting in. To make things easier the brothers Frankenstein moved, along with their creations, to a new land where monsters could live in peace. Thus, Monsterland was born. Now one of the brothers has gone missing and Monsterland is being overrun by evil, and it is up to an unlikely group of heroes to step up and save the day for monsters everywhere!  Monster Force is a video game released in 2002 for the Game Boy Advance. It was developed by Digital Eclipse Software and published by Vivendi Universal Games. A planned PlayStation version of the game was to be released in 2001 by Konami, but this never achieved fruition.' FROM games WHERE igdb_id = 49390 ON CONFLICT (game_id, language_code) DO NOTHING;
