INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'StarFlyers: Royal Jewel Rescue', 'Zoom off with the StarFlyers and see how this dilemma turns into an amazing outer-space mission to rescue the Royal Jewels! Explore wacky planets. Solve puzzles to find the Jewels. Use quick-thinking and logical-reasoning skills to uncover clues and earn valuable galaxy seeds. Reward yourself by trading galaxy seeds for astro-prizes — fun animations and printable activities. The Citizens of Planet Pop-A-Lot are counting on you!' FROM games WHERE igdb_id = 122950 ON CONFLICT (game_id, language_code) DO NOTHING;
