INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rugrats: I Gotta Go Party', 'Get ready for an all-new multi-player party game as Tommy plays hide `n seek with all of his friends. If you help Tommy find the other Rugrats you can unlock outrageous party games such as Angelica?s Cookies, Phil?s Mud Pies, Sandbox Blues and many more! The more Rugrats that you can find, the more party games that become unlocked. Designed for multiplayer competition, this game is packed with hours and hours of gaming on the go! Better hurry - the fun doesn?t begin until you find the first Rugrat.' FROM games WHERE igdb_id = 2794 ON CONFLICT (game_id, language_code) DO NOTHING;
