INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Santa Claus Jr. Advance', 'Europe-only platform game release, starring a zany kid who takes after Santa Claus. Explore 12 massive, unique worlds with 36 challenging levels. Encounter more than 30 different enemies and figure out their weak points to defeat them. The publisher bills the game as having an intuitive control system that offers simple pick-up and play gameplay. In addition to the main stages, there are also bonus levels featuring a wide range of challenges. Other features include two difficulty levels.' FROM games WHERE igdb_id = 49338 ON CONFLICT (game_id, language_code) DO NOTHING;
