INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cubix: Robots for Everyone - Clash ''n Bash', 'Something strange is happening in Bubble Town. Robots are going berserk because of Solex, the stuff that gives all robots their power. You must find each of the broken robots before the evil Dr. K and hits bad ''bots do, especially the scary and powerful Kolossal!' FROM games WHERE igdb_id = 49156 ON CONFLICT (game_id, language_code) DO NOTHING;
