INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('panzer-dragoon-orta', 1672, '2002-12-19', 87, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co68yo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/purftdqojpfo4peuwref.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Panzer Dragoon Orta', 'The fourth installment of the Panzer Dragoon series has you playing Orta, a young girl who has been imprisoned by the Empire. Under a wave of attack, the prison camp is broken through by a mysterious dragon, and Orta takes it upon herself to ride the dragon, and destroy the Empire once and for all. Along the way, she will also discover her own destiny, and the mystery surrounding her new friend. Simply put, you have limited control of the dragon for most of the game, as your trigger finger will be shooting non-stop at the enemies that fly around the area. Orta will be your main source of fire-power when you simply press the fire button, but by pressing and holding, the aim cursor will change, allowing you to fire a burst of power from the dragon at whatever the cursor aims at. The dragon itself can change into three forms at a press of a button. Each form has a different style of attack and power ability. A port of the original Panzer Dragoon is included.' FROM games WHERE igdb_id = 1672 ON CONFLICT (game_id, language_code) DO NOTHING;
