INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TransWorld Snowboarding', 'TransWorld Snowboarding offers huge, vibrant, real-world snowboarding levels with natural snow kickers and ramps for launching; rails and downed trees to jib and grind on; and natural half-pipes and quarter-pipes for performing tons of tricks. But it''s not all fun and games - treacherous terrain and steep cliffs lurk around every corner!' FROM games WHERE igdb_id = 20795 ON CONFLICT (game_id, language_code) DO NOTHING;
