INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beach Life', 'Beach Life is a business strategy video game for Windows developed by Deep Red Games. The game was published by Eidos Interactive and released on September 6, 2002. In the game, players assume the role of a manager for an island holiday resort. As vacationers enjoy their stay at the resort, players must build, employ, and finance the right lodging, entertainment, and shopping establishments to please the clients and their individual needs.' FROM games WHERE igdb_id = 11822 ON CONFLICT (game_id, language_code) DO NOTHING;
