INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('super-bubble-pop', 4187, '2002-12-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3gft.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Bubble Pop', 'Super Bubble Pop is a video game of the puzzle genre released in 2002 by Runecraft. The Player is able to choose from 5 DJ poppers, including 2 unlockable ones, along with 4 grooving soundtracks. They are faced with rows of advancing bubbles of different colors. They can launch bubbles of their own. The idea is to create a row, column or stack of 3 or more bubbles. When that happens, they will pop. Each character has their own favorite bubble color and when they pop them, color energy is transferred to their special jar. Once the jar is full, the player can unleash their super special attack. During the puzzles, the player is also provided with nine different special attacks that they can obtain by getting special bubbles. The current special attack the player has is displayed on a wheel called the Torus. The game consists of 3 different 1 player difficulty modes along with a training mode, each having 50 levels of bubble popping puzzles and a 2 player mode that allows a player to compete for the higher score against a friend. Each level is allowed to be won by popping all of the bubbles or by collecting a certain amount of Level Stars.' FROM games WHERE igdb_id = 4187 ON CONFLICT (game_id, language_code) DO NOTHING;
