INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Planet Monsters', 'There is only one rule with this game - Be the last one standing no matter what! Planet Monsters must confront themselves in eight unique countries each of 5 levels. Four monsters can play at once, so arm yourself with traps, blocks, jelly guns, grenades...and a great sense of humor!' FROM games WHERE igdb_id = 49359 ON CONFLICT (game_id, language_code) DO NOTHING;
