INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('scooby-doo-night-of-100-frights', 2860, '2002-05-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1ozq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc10h9x.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Scooby-Doo! Night of 100 Frights', 'Scooby-Doo! Night of 100 Frights is a third person platform game with action elements that was developed by Heavy Iron Studios and published by THQ for the PlayStation 2, GameCube and Xbox consoles. The game was first released on May 20, 2002 in North America and was released later that year in PAL regions. It is the first Scooby-Doo! video game title to come to sixth generation consoles. The game became a Greatest Hits title in 2003.[1] The game had a follow up titled Scooby Doo: Mystery Mayhem. The game puts players in the control of Scooby-Doo in a story that revolves around him searching for the rest of the gang around a haunted mansion after they''re kidnapped by an eccentric villain. The game has twelve areas, ranging from graveyards and secret labs to fishing villages and haunted mazes. The game received mixed reviews from critics, mainly criticizing the game''s simplicity, although its massive environments staying true to the Scooby-Doo! universe was praised by critics and fans alike. Fans of the original show loved the game, feeling it was compensation for the N64 game released in 2000. The game also marks the first and only time Don Knotts did voice work for a video game, though he did do previous voice work in the Scooby-Doo universe.[2]' FROM games WHERE igdb_id = 2860 ON CONFLICT (game_id, language_code) DO NOTHING;
