INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fushigi no Dungeon: Fuurai no Shiren Gaiden - Onna Kenshi Asuka Kenzan!', 'Fushigi no Dungeon: Fuurai no Shiren Gaiden - Onna Kenshi Asuka Kenzan! is a roguelike role-playing video game developed by Neverland. It is part of the Mystery Dungeon series, and is a side story based on the Shiren the Wanderer series. It was originally released for the Dreamcast by Sega on February 7, 2002. A Microsoft Windows port would be later released on December 20, 2002 and re-released later with internet compatibility on February 27, 2004, both published by Chunsoft.' FROM games WHERE igdb_id = 80485 ON CONFLICT (game_id, language_code) DO NOTHING;
