INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cabela''s Big Game Hunter 6', 'The sixth installment in Cabela''s Big Game Hunter series gives you a choice between live action video and 3D hunting. Choose from one of six characters, each one with his or her strengths and weaknesses, and then hunt down more than 16 different animals. After the hunt, head back to the lodge to purchase authentic Cabela hunting gear. To give you a realistic hunting experience, the game''s animal behavior and game design are based on actual DNR information.' FROM games WHERE igdb_id = 80409 ON CONFLICT (game_id, language_code) DO NOTHING;
