INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pryzm Chapter One: The Dark Unicorn', 'A corrupting plague of dark magic grips the world... once lush lands have turned barren, and the inhabitants have become hostile mutant creatures. Now, join the quest of a unique young unicorn and a tenacious old troll in a desperate bid to find and destroy the source of the curse. Journey through four vast and eerie lands - each with four levels to explore.' FROM games WHERE igdb_id = 24078 ON CONFLICT (game_id, language_code) DO NOTHING;
