INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dinosaur Resurrection', 'A remake of Nihon Falcom''s 1990 dungeon RPG Dinosaur. The game now uses a 3D environment for the main visuals along with a reworked soundtrack and user interface. A mini-map has been added along with extra movement options, item shortcuts and other general re-balances to the game. The party formation system has been expanded on and some new bow skills were added.' FROM games WHERE igdb_id = 92988 ON CONFLICT (game_id, language_code) DO NOTHING;
