INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Sims Online', 'The Sims Online was the first massively multiplayer online variation on Maxis''s highly popular computer game The Sims, the second being the Online Weekend mode for The Sims Bustin'' Out, and third being The Sims Social. The game was sold in retail stores in North America and Japan and could also be downloaded worldwide through the EA.com online store, though the game was English-only and had no official translations.' FROM games WHERE igdb_id = 13152 ON CONFLICT (game_id, language_code) DO NOTHING;
