INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Buffy the Vampire Slayer', 'Buffy Summers makes her console debut in a third-person action game set within the not-so-peaceful town of Sunnydale, CA. As the 17-year-old Chosen One, Buffy must use her heightened strength and agility to defeat vampires, zombies, and other demons attracted to the town''s dangerous proximity to a Hellmouth. Based on the UPN television series known for its unusual blend of action, suspense, comedy, and drama, the game takes place around the timeframe of the show''s first and second seasons.' FROM games WHERE igdb_id = 5760 ON CONFLICT (game_id, language_code) DO NOTHING;
