INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fighter Maker 2', 'Fighter Maker 2 (FM2) for the PS2 was another entry in the Designer Series from Agetec Inc. It was released in November 2002. It is similar to the original, but with more advancements in character design, movement, and attacks. As with the first, the game was met with lukewarm reviews, mainly due to its cumbersome interface and the lack of bells and whistles that were featured in most fighting games at the time.' FROM games WHERE igdb_id = 43644 ON CONFLICT (game_id, language_code) DO NOTHING;
