INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Masq', 'Masq is an interactive comic with typical soap opera elements such as love, betrayal and murder, and the portrayal of characters in a pulp fiction fashion. It consists of five seamless episodes, which can be finished in an hour, but depending on the choices different storylines and plot twists can be explored.' FROM games WHERE igdb_id = 93353 ON CONFLICT (game_id, language_code) DO NOTHING;
