INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Scally''s world of problems', 'Scally''s world of problems is an educational puzzle game released for windows 95 by Topologika Software  In the game you explore many pre-designed stages in an attempt to get to the end.  There are many different styles to the stage, merely changing the tiles and music.  These themes consist of: Atmosphere, Forests, Land, Oceans, Space, Underground, Waglings and Zoo  The game also includes a level designer in which you can choose the tilesets, size and of course layout.' FROM games WHERE igdb_id = 110425 ON CONFLICT (game_id, language_code) DO NOTHING;
