INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 2000 Series Vol. 11: The Offroad Buggy', 'Can you keep up with the Dirt Track Devils? Give it your best as you race diverse ATV''s across snowy mountain passes, treacherous forest tracks and sunny beaches. These tracks will test the limits of your driving skill. Powerslide, jump and skid your way to victory in the challenging OFF ROAD RACE mode, take on the time trial challenge in the ever-changing GYMKHANA event, or beat your buddies in the VS BATTLE RACE mode.' FROM games WHERE igdb_id = 70557 ON CONFLICT (game_id, language_code) DO NOTHING;
