INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Centre Court: Hard Hitter', 'Take to centre court as you lob, slice, volley and smash your way to victory! With phenomenal ball physics, silky smooth graphics and addictive gameplay this game serves as an ace past the competition. Play against a friend to experience just how addictive Centre Court: Hard Hitter can be!  Are you a Hard-Hitter? Or will you walk away from the challenge? The ball''s in your court.' FROM games WHERE igdb_id = 43382 ON CONFLICT (game_id, language_code) DO NOTHING;
