INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alfred Hitchcock Presents: The Final Cut', 'Robert Marvin-Jones is a billionaire recluse who decides to pay homage to Alfred Hitchcock by making a film in his backyard; however his film crew have gone missing and possibly been brutally murdered. Meanwhile, private detective Joseph Shamley has psychic power. Jones'' niece, a mute named Alicia, asks Shamley to use his powers of deduction to solve the mystery' FROM games WHERE igdb_id = 27392 ON CONFLICT (game_id, language_code) DO NOTHING;
