INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Freekstyle', 'You''ve been waiting for it and now it''s here - FreekStyle - the ultmate go-for-broke freestyle motocross experience. EA SPORTS BIG brings you motoX like you''ve never seen it - pushing even the greatest riders to go full throttle while pulling the craziest tricks on awesome tracks. FreekStyle isn''t just about being the fastest rider; it''s about being absolutely fearless. Backflips, Tsunamis and Mulisha Airs - you can do it all against the world''s craziest moto daredevils.' FROM games WHERE igdb_id = 3919 ON CONFLICT (game_id, language_code) DO NOTHING;
