INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('twisted-metal-black-online', 22240, '2002-09-27', 40, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1p3r.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8cle.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Twisted Metal: Black Online', 'First offered as a freebie in the United States with purchase of a PlayStation 2 Network Adapter for its initial release (and later included again for free as part of the Greatest Hits package for Twisted Metal: Black), this online version of the hit car combat game features all of the cars and carnage of the original game across all 18 stages (including all full stages and mini-stages from the full game) of Twisted Metal: Black. The violent cinemas and story mode were excluded in this network-only version (partially to tone the ESRB rating down to a T), but the multiplayer modes for online play still include all four modes – deathmatch, last man standing, collector, and manhunt – with options for power relic modifiers to be turned on. Online play originally was limited to only 4 players (2 over 56k), and chat functionality was not included. However, via server fixes, the player count was upped to 8 online via broadband, and a chat function via USB keyboard/on-screen input was also made unlockable when a secret code is entered on the lobby screen.' FROM games WHERE igdb_id = 22240 ON CONFLICT (game_id, language_code) DO NOTHING;
