INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple Characters 2000 Series Vol.8: Kagaru Ninja Tai Gatchaman - The Shooting', 'Gatchaman: The Shooting is a vertical shoot ''em up based on the Japanese manga/anime with the same name (Known as Battle of the Planets in the US). You select any of the four characters featured in the game (Ken the Eagle, Joe the Condor, Jun the Swan and Jinpei the Swallow) and shoot your way through 4 action filled stages with increasing difficulty either running riding a vehicle or flying, to in the end defeat the evil Berg Katse. Along the way you can collect power-ups for your weapons to increase your chances of survival.' FROM games WHERE igdb_id = 43757 ON CONFLICT (game_id, language_code) DO NOTHING;
