INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Utawarerumono', 'Hakuoro, a man who wakes up in a tiny backwoods village near the mountains with heavy injuries, no memory, and a mask he cannot remove. After being nursed back to health by Eruruw, the girl who found him lying at the point of death in the forest, he starts to view the village as his new home. But when an oppressive ruler threatens the peaceful life of Hakuoro and his newfound friends and family, they find themselves hurtled towards war, chaos, and a destiny far greater than any of them imagined.' FROM games WHERE igdb_id = 24080 ON CONFLICT (game_id, language_code) DO NOTHING;
