INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Icewind Dale II: Collector''s Edition', 'This Collector''s Edition of Icewind Dale II, in addition to the game, includes: - A cloth map of the Spine of the World - Dice - A poster with a creature list - Trading cards with characters and creatures from the game - A bonus CD with in-game extras and soundtrack - Spiral-bound manual - Black Isle Studios stickers - Writing tablet' FROM games WHERE igdb_id = 232152 ON CONFLICT (game_id, language_code) DO NOTHING;
