INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars: Racer Revenge', 'Star Wars: Racer Revenge is a Star Wars video game that involves high speed racing. It is the sequel to Star Wars Episode I: Racer. The story takes place eight years after The Phantom Menace, Sebulba wants revenge on Anakin Skywalker. Unlike its predecessor, the player is unable to continue racing if they crash their pod.' FROM games WHERE igdb_id = 19419 ON CONFLICT (game_id, language_code) DO NOTHING;
