INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kowai-shashin-shinrei-shashin-kitan', 137561, '2002-05-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4bbb.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kowai Shashin: Shinrei Shashin Kitan', 'Kowai Shashin is a horror game released for the Sony Playstation in 2002, it is vagyuely similar to the Fatal Frame series. Gameplay consists of finding a spirit in a creepy photograph, and catching it trough a quick time event. There´s an urban legend around the game, considering it a cursed one, because of supposed deaths and hauntings during the development (which isn''t true, at least, no one died during the making of the game).' FROM games WHERE igdb_id = 137561 ON CONFLICT (game_id, language_code) DO NOTHING;
