INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Westlife: Fan-O-Mania', 'Are you a real fan? Now you can prove it! Dive into the exciting world of WESTLIFE with a unique interactive Trivia Quiz Game! Includes 500 challenging questions on the Band - and you thought you knew everything already! Exclusive videos - never broadcast before! Exclusive audio - never heard before! Exclusive pictures - never seen before! Score 100% and unlock an exclusive video interview with one member of the band! Play alone or compete with your friends - up to 4 players.' FROM games WHERE igdb_id = 91892 ON CONFLICT (game_id, language_code) DO NOTHING;
