INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disaster Report', 'Zettai Zetsumei Toshi is a survival action-adventure video game created by Irem. It is the first game in the Zettai Zetsumei Toshi series. The game deals with the characters'' survival and escape from the slow collapse of an artificial island. While dodging falling buildings and debris from periodic earthquakes, the player must find a way off the island. In addition, the main character, a reporter, must investigate the reasons for the disaster.' FROM games WHERE igdb_id = 11695 ON CONFLICT (game_id, language_code) DO NOTHING;
