INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Digimon Battle', 'Digimon Battle, originally released in South Korea as Digimon RPG, is a free to play micro-transaction supported massively multiplayer online role-playing game in a setting based on that of the Digimon media franchise, specifically the Digimon Tamers anime. The game was first released in South Korea, but an English version was released on April 14, 2010 by WeMade Entertainment titled Digimon Battle, which ran for 3 years. The South Korean version still runs to this day.' FROM games WHERE igdb_id = 66461 ON CONFLICT (game_id, language_code) DO NOTHING;
