INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'White Heart Baekgu 3', 'Third in a trilogy of South Korean platformers based on the animated film Hayan Maeum Baekgu, itself based on the 1993 news story surrounding the dog which travelled over 260km in six months to reunite with its previous owner. This entry has almost nothing to do with the previous titles, and received official localisation in the CIS under the name "Rex 2." Also includes an electronic pet application.' FROM games WHERE igdb_id = 209292 ON CONFLICT (game_id, language_code) DO NOTHING;
