INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('baldr-force', 6714, '2002-11-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2wfv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sceluc.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Baldr Force', 'In the future, cyberspace has become exceedingly dominant. Armed conflicts and cyber-terrorism flourished. Giant mechas known as Simulacrums are utilized for battles within the cyberspace. Toru Souma is an expert hacker of the Steppenwolf group, which specializes in stealing and selling valuables from servers. One day, Toru was caught in a battle between the military organization FLAK and a terrorist group. In a series of events, his friend was killed. Stricken by grief, Toru decides to avenge his death and joins FLAK, only to unravel a much larger conspiracy. Baldr Force is a follow-up to Baldr Bullet. It uses a different scenario and character cast, but is very close to its predecessor gameplay-wise. Like in Baldr Bullet (and unlike Baldrhead), there is no exploration of any kind in the game, and all battles take place within confined areas as dictated by the plot. Combat system is nearly identical to that of the previous game, with the exception of "force crashes", powerful attacks that can be equipped on the protagonist''s mech. The game''s plot may branch depending on the decisions taken by the player during the visual novel-like portions.' FROM games WHERE igdb_id = 6714 ON CONFLICT (game_id, language_code) DO NOTHING;
