INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shootout Pool', 'A 3-D pool game where players use a real cue stick to hit on-screen cueball to effect the on-screen billiard balls. Shootout Pool was produced by Sega in 2002. Sega released 593 machines in our database under this trade name, starting in 1960. Sega was based in United States. Other machines made by Sega during the time period Shootout Pool was produced include: Super Major League 2001, Power Smash 2, InuNoOsanpo, Crackin'' DJ Part 2, Cyber Troopers Virtual On Force, House of The Dead 3, Virtua Striker 3, Beach Spikers, Virtua Striker 2002, and Maze Of The Kings, The' FROM games WHERE igdb_id = 317528 ON CONFLICT (game_id, language_code) DO NOTHING;
