INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Age of Sail II: Privateer''s Bounty', 'Lead the wooden fleets of the world''s most powerful nautical powers into battle in the new standard in naval combat simulation, Age of Sail II - Privateer''s Bounty. Never before has any aspect of nautical combat been so faithfully reproduced, from advanced sailing tactics to the handling of your crew.' FROM games WHERE igdb_id = 9429 ON CONFLICT (game_id, language_code) DO NOTHING;
