INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Run Like Hell: Hunt or Be Hunted', 'Run Like Hell (also known as RLH) is a third-person shooter video game designed by Digital Mayhem and released by Interplay for the PlayStation 2 in late 2002 and for Xbox in early 2003. Run Like Hell is set on a space station in the distant future. It features the voice talents of Lance Henriksen, Thomas F. Wilson, Clancy Brown, Kate Mulgrew, Michael Ironside and Brad Dourif. The game also features the music of Three Days Grace and Breaking Benjamin, including an exclusive music video of their song "Polyamorous". The later Xbox version includes one new level and several new alien creatures, while several optional player character skins and additional minigames can also be downloaded via Xbox Live or the Xbox Exhibition 3 demo disc.' FROM games WHERE igdb_id = 6011 ON CONFLICT (game_id, language_code) DO NOTHING;
