INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 2000 Honkaku Shikou Vol.004: The Mahjong', 'The Mahjong is a mahjong game featuring different difficulty levels (From beginner to advanced), 30 different kind of professional opponents (men & women) and 2 different game modes, Annual Waging War (sort of a story mode) and free Waging War (Sort of a free mode in which the player can play against the professional players that he defeats in the story mode), featuring real tournament names. The player can choose at the beginning of the game between a male or a female character.' FROM games WHERE igdb_id = 203346 ON CONFLICT (game_id, language_code) DO NOTHING;
