INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kingdom Hearts Final Mix', 'Originally released only in Japan on December 26, 2002, Kingdom Hearts Final Mix has several events and a number of gameplay tweaks that are not in previous releases. Spoken dialogue is in English, with Japanese subtitles. New scenes, clarifying certain plot points, such as Riku''s journey and foreshadowing of Kingdom Hearts II, were included, but no new dialogue was recorded. A gameplay option allows the player to skip cutscenes after seeing them once. The optional bosses first included in the English version were introduced to Japanese players for the first time, along with a new fight against "Unknown Man," in an attempt to raise interest for the sequel.' FROM games WHERE igdb_id = 20283 ON CONFLICT (game_id, language_code) DO NOTHING;
