INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('libertys-kids', 186062, '2002-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4b7c.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sctlyv.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Liberty''s Kids', 'Approaching the last quarter of the 18th century, a tidal wave of change is poised to engulf the American colonies. Sarah Phillips and James Hiller, two young reporters working for Benjamin Franklin, adventure in search of the ultimate scoop for the front page of the Pennsylvania Gazette. Kids encounter soldiers, spies, Indians, Loyalists, statesmen, and townsfolk in a series of adventures that place them right in the middle of one of the most important eras of America''s history, the American Revolution. The primary goal of Liberty''s Kids is to provide kids, ages 7 to 12, with a fresh and exciting experience of the extraordinary period in American history, 1773 to 1789. Kids gain insight into the complex ideas, perspectives, and motivations for the American Revolution. Seven historical events set in colonial America, including the Boston Tea Party, the Declaration of Independence, and the crossing of the Delaware, await kids in this exciting educational software game. Each event is can be replayed from different perspectives. Plus, kids can watch mini-movies from the PBS Kids animated series, explore Ben Franklin''s inventions, create and print their own newspaper, meet famous historical figures, and much more.' FROM games WHERE igdb_id = 186062 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 186062 AND ge.slug = 'point-and-click' ON CONFLICT DO NOTHING;
