INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bird Hunter 2003: Legendary Hunting', 'In this sequel to Bird Hunter, the player assumes the role of a hunter, going around hunting for most forms of bird he can find (including turkeys) across the USA. There is a wider variety of birds to hunt and kill, complete with more detailed bird actions and sounds. It is also possible to utilize decoys to lure the prey or just wait and shoot them down from the sky.' FROM games WHERE igdb_id = 69525 ON CONFLICT (game_id, language_code) DO NOTHING;
