INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MechAssault', 'MechAssault was the first BattleMech video game published for the Xbox. Developed by Day 1 Studios and published by Microsoft, MechAssault was initiated when Denny Thorley of Day 1 Studios approached Jon Kimmich of Microsoft about developing an original BattleTech game built from the ground up to support console play.[1] "MechAssault" was released in November of 2002. A sequel, MechAssault 2: Lone Wolf, was released on December 28, 2004. Both games are set in the BattleTech fictional universe' FROM games WHERE igdb_id = 5910 ON CONFLICT (game_id, language_code) DO NOTHING;
