INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 2000 Series Ultimate Vol. 4: Urawaza Ikasa Mahjong Gai', 'Urawaza Ikasa Mahjong Gai is a mahjong game that features 2 different game modes, the first one is a story mode in which the player will advance through the story defeating the opponents, the other game mode is a free mode in which the player can play mahjong matches againts 3 computer opponents (that are the one that he can unlock in the story mode).' FROM games WHERE igdb_id = 203351 ON CONFLICT (game_id, language_code) DO NOTHING;
