INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kikou Heidan J-Phoenix: Burst Tactics', 'Kikou Heidan J-Phoenix: Burst Tactics is an action game on Playstation 2 published by Takara, in 2002. This game is a side story of Kikou Heidan J-Phoenix, featuring new PF and characters. In addition, a cooperative attack with fellows called Combination Burst has been introduced. If you import the data of Joshou-hen and Kikou Heidan J-Phoenix, you can get the story after the main ending and hidden PF.' FROM games WHERE igdb_id = 214914 ON CONFLICT (game_id, language_code) DO NOTHING;
