INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Summoner 2', 'The player takes on the role of Maia, Queen of Halassar, who is the goddess Laharah reborn, and can transform herself into a variety of "summonable" creatures. The game''s story revolves around Maia''s quest to heal the World Tree, Eleh, which was shattered by the Storm.' FROM games WHERE igdb_id = 4186 ON CONFLICT (game_id, language_code) DO NOTHING;
