INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jockey''s Road', 'Jockey''s Road was developed by veteran horse-racing game developer Progress, and was intended to bring a new role-playing element into the genre. As in previous horse-racing games, players assume the role of a jockey and race on a variety of tracks. More than 300 horses, which are randomly generated in polygon form using data inputted by the user, are featured in the game. The script for the game was written by Kenji Terada, who is known for his work as a scriptwriter for Final Fantasy I, Final Fantasy II, and Final Fantasy III on the Famicom.' FROM games WHERE igdb_id = 62228 ON CONFLICT (game_id, language_code) DO NOTHING;
