INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('inuyasha-a-feudal-fairy-tale', 45004, '2002-12-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coar84.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc102z9.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Inuyasha: A Feudal Fairy Tale', 'Inuyasha: A Feudal Fairy Tale is a 2D fighting game starring characters from Rumiko Takahashi''s manga and animé series, Inuyasha. The story centers around 15-year old high school student Kagome Higure, who inadvertently slips back in time to feudal Japan, where she becomes embroiled in a quest to locate shards of the Sacred Jewel of the Four Souls. "Feudal Fairy Tale," the game''s main mode of play, follows this escapade and requires players to engage in a series of battles and mini-games in order to obtain the coveted shards. Initially, only Kagome and her half-demon companion Inuyasha are playable, but as players journey through the game, acquiring shards, more characters become available. Each character is able to perform both strong and weak attacks, as well as throws and counter attacks. Players can also execute more powerful combination maneuvers, including special and super attacks, which can only be initiated when the Spiritual meter is filled. Additionally, specific attacks can cause opponents to drop shards that, once claimed, will fill the Spiritual meter more quickly.' FROM games WHERE igdb_id = 45004 ON CONFLICT (game_id, language_code) DO NOTHING;
