INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('celtic-kings-rage-of-war', 11271, '2002-08-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3dcj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar21lk.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Celtic Kings: Rage of War', 'Julius Caesar wants to expand his already massive empire and he has his sights set on the lush countryside of Gaul. Celtic Kings: Rage of war brings you the excitement of the Roman conquests in two modes: strategic and adventure. In strategic mode, you play as either the Romans or the Gauls in a world where tactical and strategic maneuveres are the key to victory. In adventure mode you take on the role of Larax and the battle the warring tribes who have raided your village and killed your wife. Two exciting game modes, one action-packed conquest - let the best warrior win!' FROM games WHERE igdb_id = 11271 ON CONFLICT (game_id, language_code) DO NOTHING;
